programs.sol:
"""A surface-word mixture: be/been and arrangement versus death/survival.

The strongest positives are the token ' be' and forms of 'been'. Their size
is set by the last five tokens: capability (can be) exceeds future (will be),
and has been exceeds had been. Intervening words attenuate be; existential
there and a few infinitive constructions adjust it further.

Death/survival vocabulary is negative, while placement/configuration words
and several other languages' forms of be are positive. CJK compounds receive
smaller responses than standalone 死 (death) or 置 (placement); 位置 (location)
is nearly neutral. Case and leading spaces matter. Decaying function-word
counts distinguish English die/dies from weaker German article/demonstrative
uses. Everything unlisted is zero. State resets at each document boundary.
These are lexical rules, not a general semantic or syntactic parser.
"""
READS = ()

ENGLISH_CUES = frozenset('the and of to have has is was were you with will '
                         'would can could should must not this that'.split())
GERMAN_CUES = frozenset('der das den dem des ein eine einer eines einem einen '
                        'und ist sind auch nicht für auf über durch gegen '
                        'zu im mit sich wir ich er sie'.split())

BE_CONTEXT = {
    'can': 1.80, 'cannot': 1.75, 'could': 1.51,
    'will': 0.46, 'would': 0.41, 'shall': 0.83,
    'may': 1.16, 'might': 0.90, 'must': 1.24,
    'should': 1.17, 'to': 0.91,
    "'ll": 0.35, '’ll': 0.35, "'d": 0.37, '’d': 0.37,
}
PERFECT = {
    'has': 1.27, 'have': 1.00, 'had': 0.85, 'having': 0.90,
    'hasn': 1.35, 'haven': 1.05, 'hadn': 0.95,
    "'s": 0.85, '’s': 0.85, "'ve": 0.85, '’ve': 0.90,
}
DEATH_AND_SURVIVAL = {
    'death': -1.17, 'deaths': -1.01, 'dead': -1.22,
    'died': -2.82, 'dying': -1.28,
    'killed': -0.71, 'deceased': -1.40, 'murdered': -0.81,
    'alive': -0.60, 'survive': -0.58, 'survived': -0.74,
}
PLACEMENT = {
    'configuration': 0.70, 'configurations': 0.63,
    'configure': 0.60, 'configured': 0.58,
    'arrangement': 0.98, 'arrangements': 0.60, 'arranged': 0.27,
    'placement': 1.03, 'placed': 0.46, 'positioning': 0.45,
    'setup': 0.43, 'deployed': 0.47,
}
OTHER_BE_FORMS = {
    'être': 1.42, 'быть': 1.33, 'być': 1.09, 'essere': 0.90,
    'ser': 0.70, 'sido': 0.80, 'été': 0.62,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, language = (), 0.0
    else:
        _, history, language = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if token == ' be':
        value = 0.28
        for j in range(len(history) - 1, -1, -1):
            aux = history[j]
            if aux not in BE_CONTEXT:
                continue
            distance = len(history) - j
            value = 0.28 + (BE_CONTEXT[aux] - 0.28) * 0.84 ** (distance - 1)
            before = history[j - 1] if j else ''
            if before == 'there' or 'there' in history[j + 1:]:
                value -= 0.3 if aux in {'will', 'would', 'to'} else 0.5
            if aux == 'to':
                if before in {'need', 'needs', 'has'}:
                    value += 0.43
                elif before == 'have':
                    value += 0.17
                elif before == 'going':
                    value -= 0.31
                elif before in {'seem', 'seems', 'appear', 'appears', 'considered'}:
                    value -= 0.18
            break
    elif lower == 'been':
        value = 0.95
        for j in range(len(history) - 1, -1, -1):
            aux = history[j]
            if aux not in PERFECT:
                continue
            value = PERFECT[aux]
            before = history[j - 1] if j else ''
            if before == 'there':
                value -= 0.4
            elif aux == 'have' and before in {'would', "'d", '’d'}:
                value -= 0.42
            elif aux == 'have' and before == 'could':
                value += 0.23
            break
    elif lower in {'die', 'dies'}:
        if language < -0.5:
            value = -1.7 if lower == 'die' else -2.3
        elif lower == 'dies':
            value = -0.85 if word.islower() else -1.15
        elif word.islower():
            # German accusative prepositions suppress the article's response.
            after_preposition = history and history[-1] in {
                'auf', 'über', 'durch', 'gegen'
            }
            value = 0.0 if after_preposition else -0.33
        else:
            value = -0.55
    elif lower in DEATH_AND_SURVIVAL:
        value = DEATH_AND_SURVIVAL[lower]
        if word != lower:
            value *= 0.65
    elif word in OTHER_BE_FORMS:
        value = OTHER_BE_FORMS[word]
        if not token.startswith(' '):
            value *= 0.4
    elif '死' in word:
        if word == '死':
            value = -2.8
        elif word.startswith('死') or word == '不死':
            value = -1.4
        elif word.endswith('死亡'):
            value = -1.0
        else:
            value = -0.4
    elif word == '去世':
        value = -2.15
    elif '置' in word:
        if '位置' in word:
            value = 0.07
        elif word == '置':
            value = 3.6
        elif word in {'布置', '安置', '前置'}:
            value = 2.0
        else:
            value = 1.0
    elif lower in PLACEMENT:
        value = PLACEMENT[lower]
    elif lower == 'be':
        value = 0.3 if word.isupper() else 0.15
    else:
        value = 0.0
    language = language * 0.95 + (lower in GERMAN_CUES) - (lower in ENGLISH_CUES)
    return (doc, (*history[-4:], lower), language), value

programs.luna:
"""Approximate this component's sparse word-linked responses."""
READS = ()

BE_FORMS = {"be", "been"}
DEATH_FORMS = {"death", "deaths", "died"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in BE_FORMS:
        return None, 1.0
    if word in DEATH_FORMS:
        return None, -1.0
    return None, 0.0

programs.sol:
"""A negative response to the beginning of a document and its first separators.

The first token is scored by character type and word class. Subsequently, the
negative response fades with document position, more slowly for sentence ends
than for commas. Periods after numbers or abbreviations are weaker. Chat role
labels immediately after an opening message marker have their own start pulse.
"""
import math

READS = ()
FUNCTION_WORDS = set("""
    a an of to in on at for with from by as and or but
    i you he she we they it my your his her our their this that these those
""".split())
CODE_OPENERS = {'import', 'package', 'using', 'include', 'def', 'class',
                'function', 'public', 'private', 'export'}
ABBREVIATIONS = {'dr', 'mr', 'mrs', 'ms', 'sr', 'jr', 'st', 'vs', 'etc'}
START_PUNCTUATION = {
    '.': 5.70, ',': 5.19, '。': 4.0, '，': 3.4, '、': 2.6,
    ':': 2.47, ';': 2.67, '-': 2.25, '?': 2.25, '/': 1.80,
    '"': 1.71, ')': 1.67, '(': 1.17, '#': 1.09, '*': 1.06,
    '[': 0.62, ']': 0.80, '{': 0.78, '}': 0.56, '=': 0.47,
}


def start_strength(token):
    word = token.strip()
    lower = word.lower()
    if token.startswith('<|'):
        return 1.16
    if token.isspace():
        if '\n' in token:
            return 0.79 / token.count('\n') ** 0.6
        if '\t' in token:
            return 0.52 / (1 + token.count(' ') * 0.2)
        return 0.93 / len(token) ** 0.4
    if word in START_PUNCTUATION and not token.startswith(' '):
        strength = START_PUNCTUATION[word]
        if '\n' in token:
            strength /= 1 + 1.3 * token.count('\n')
        return strength
    if word.isdigit():
        return 0.96 if word.isascii() else 0.22
    if '�' in word:
        return 0.20
    if word and all(c == '#' for c in word):
        return min(1.65, 1.09 + 0.55 * (len(word) - 1))
    if word and not any(c.isalnum() for c in word):
        strength = 2.2 if word.endswith(('.', ',')) else 0.8
        return strength if not token.startswith(' ') else strength * 0.6
    if lower == 'the':
        return 0.88
    if lower in FUNCTION_WORDS:
        return 0.60
    if lower in CODE_OPENERS and not token.startswith(' '):
        return 0.90
    if not word.isascii():
        return 0.21
    if token.startswith(' '):
        return 0.22
    if len(word) == 1:
        return 0.47
    if word.isupper():
        return 0.20
    return 0.48 if word[:1].isupper() else 0.34


def pulse(position, strength, power, decay):
    return strength * math.exp(-position / decay) / (position + 1) ** power


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    state = (doc, position, token)
    if position == 0:
        return state, float(-start_strength(token))

    bump = math.exp(-position / 60)
    value = -0.005 + 0.02 * bump - pulse(position, 0.25, 2.0, 60)
    if token == '.':
        before = previous.strip()
        if before.lower() in ABBREVIATIONS:
            value = 0.04
        elif len(before) <= 3 and before.isupper():
            value = 0.01 + 0.10 * bump - pulse(position, 0.9, 0.5, 20)
        elif before.isdigit():
            value = 0.06 * bump - pulse(position, 3.2, 1.3, 80)
        else:
            value = -0.002 + 0.10 * bump - pulse(position, 4.2, 0.8, 14)
    elif token in {'.\n', '.\n\n', '。', '。\n'}:
        value = 0.01 + 0.03 * bump - pulse(position, 2.0, 0.3, 8)
    elif token == ',':
        value = -0.01 + 0.06 * bump - pulse(position, 1.9, 0.7, 5)
    elif token in {')', ')\n', ');\n'}:
        value = -0.008 + 0.04 * bump - pulse(position, 0.8, 0.0, 2)
    elif token in {'\n', '\n\n'}:
        value = 0.04 * bump - 0.45 / (position + 1) ** 1.1
    elif token == '<|im_start|>':
        value = 0.08 - pulse(position, 1.2, 1.0, 8)
    elif position == 1 and previous == '<|im_start|>' and token in {
            'user', 'assistant', 'system'}:
        value = -0.47
    return state, float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 1281: a "start of document, full stop or comma" detector.

What it does: the component is almost silent through the body of a text. It responds only
near the start of a document. The model restarts positions at each document and at each
packed row, so the first token of a row counts as a document start. There it goes
negative. The response is strongest when the token is a full stop or comma ("." ","), and
it fades within about six tokens. Other punctuation at the start is moderately negative,
and digits, special chat tokens and ordinary words are weakly negative.

Prediction, with k = index of the token within its document (k = 0 is the first token):
  "." or "," : k = 0: -5.5, k = 1: -1.0, k = 2 or 3: -0.6, k = 4 or 5: -0.35, later: 0
  other punctuation, k = 0: -1.5
  digit or "<|im_start|>", k = 0: -1.0
  any other token, k = 0: -0.4
  everything else: 0
"""

import unicodedata

READS = ()

DOT_TIER = (-5.5, -1.0, -0.6, -0.6, -0.35, -0.35)  # "." or "," by position k
PUNCT_CATEGORIES = ("P", "S")  # Unicode punctuation and symbol classes


def is_punct(s):
    return len(s) > 0 and all(unicodedata.category(c)[0] in PUNCT_CATEGORIES for c in s)


def step(carry, prefix, upstream):
    # carry: (k, document id of the previous token), or None at a row's first token.
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[1]:
        k = 0  # first token of a document (or of a row)
    else:
        k = carry[0] + 1
    token = prefix.token_strings[-1]
    if token in (".", ","):
        value = DOT_TIER[k] if k < len(DOT_TIER) else 0.0
    elif k == 0:
        if is_punct(token):
            value = -1.5
        elif token.isdigit() or token == "<|im_start|>":
            value = -1.0
        else:
            value = -0.4
    else:
        value = 0.0
    return (k, doc), float(value)

programs.luna:
"""Track the component's strong response near a document boundary."""

import unicodedata

READS = ()

BASE_BY_AGE = (
    -0.743, -0.129, -0.055, -0.058,
    -0.026, -0.021, -0.005, -0.019,
)
EARLY_PUNCTUATION = (-0.388, -0.220, -0.344, -0.163)
EARLY_OTHER = (-0.093, -0.031, -0.016, -0.006)


def _is_punctuation(text):
    return bool(text) and all(
        unicodedata.category(char)[0] in "PS" for char in text
    )


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        age = 0
    else:
        age = carry[1] + 1

    token = prefix.token_strings[-1].strip()
    if age == 0:
        if token == ".":
            value = -4.736
        elif token == ",":
            value = -5.190
        elif _is_punctuation(token):
            value = -0.958
        elif token.startswith("<|") and token.endswith("|>"):
            value = -1.156
        elif token.isdigit():
            value = -0.959
        elif not token:
            value = -0.712
        elif token.isalpha():
            value = -0.392
        else:
            value = -0.50
    elif age < 5:
        if _is_punctuation(token):
            value = EARLY_PUNCTUATION[age - 1]
        else:
            value = EARLY_OTHER[age - 1]
    elif age == 7 and _is_punctuation(token):
        value = -0.087
    else:
        value = BASE_BY_AGE[age] if age < len(BASE_BY_AGE) else -0.00481

    return (document, age), value

programs.haiku:
"""Predicts layers.0.mlp.down_proj:1282 from the current token alone.

This component is a lexical detector for "chief / principal / principle" words: it
fires on the English words chief, principal, principle(s), senior, deputy and their
translations (глав-, 主任, 高级, принцип, 原理), and on the empty call parentheses "()"
of code. Everything else is predicted as 0.
"""

READS = ()

# Top-rank and main-thing words, in English (value = typical activation).
TOP = {"chief": 2.5, "chiefs": 1.6, "chiefly": 1.5, "principal": 4.0,
       "senior": 1.3, "seniors": 0.5, "superintendent": 1.0, "deputy": 0.7,
       "chairman": 0.6, "junior": 0.6, "vice": 0.4, "officer": 0.4,
       "advisor": 0.5, "adviser": 0.5, "director": 0.3}
# Words for principle / fundamental / doctrine.
PRINCIPLE = {"fundamental": 0.5, "fundamentally": 0.5, "doctrine": 0.35,
             "doctrines": 0.35, "substantive": 0.7, "foremost": 0.4}
# The same ideas in other languages and scripts.
OTHER = {"主任": 1.5, "副主任": 0.5, "高级": 1.0, "资深": 1.0, "主管": 1.0,
         "主力": 1.0, "原理": 1.1, "原则": 0.8, "原則": 0.6, "主体": 0.8,
         "主要": 0.6, "رئيس": 1.0, "основ": 0.6}

CODE_CALL = 0.45  # tokens containing "()", e.g. "()", "().", "();\n", " ()"


def word_value(word):
    if word in TOP:
        return TOP[word]
    if word in PRINCIPLE or word in OTHER:
        return PRINCIPLE.get(word, OTHER.get(word, 0.0))
    if word == "principal":
        return 4.0
    if word.startswith("princip"):
        return 1.8  # principle, principles, and word-pieces of them
    if word.startswith("глав"):
        return 1.5
    if word.startswith("принцип"):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    value = word_value(text.strip().lower())
    if value == 0.0 and "()" in text:
        value = CODE_CALL
    return carry, float(value)

programs.luna:
"""Mark principle/principal words, leadership titles, and empty-call syntax."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().casefold()

    if "princip" in word or "принцип" in word:
        return None, 1.7
    if "()" in token:
        return None, 0.56

    # Titles and roles related to a principal or senior person.
    if word.startswith(("director", "senior", "vice", "chief", "chair")):
        return None, 0.8
    if word.startswith(("глав", "主任")):
        return None, 1.0
    if "fundamental" in word:
        return None, 0.5
    return None, 0.0

"""Predict a strong response to 'near' and weaker responses to related words.

The other positive words describe closeness, approximation, or relative
position and time; all unrelated tokens are predicted as zero.
"""
READS = ()

NEAR = {'near': 8.0, 'nearby': 1.5}
CLOSENESS = {'nearly': 2.5, 'nearest': 2.5, 'almost': 1.8,
             'around': 1.7, 'vicinity': 1.5, 'closest': 1.3,
             'close': 1.25, 'neighborhood': 1.1}
RELATIONS = {
    'toward': 1.15, 'towards': 1.15, 'below': 1.1, 'away': 1.0,
    'above': 0.9, 'approximately': 0.9, 'either': 0.85, 'next': 0.8,
    'neither': 0.7, 'after': 0.7, 'along': 0.64, 'immediate': 0.64,
    'under': 0.55, 'beyond': 0.55, 'soon': 0.56, 'before': 0.48,
    'outside': 0.44, 'off': 0.5, 'opposite': 0.68, 'approaching': 0.67,
    'far': 0.85, 'behind': 0.3, 'surrounding': 0.7,
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(",.;:!?()[]{}'\"-–—")
    value = NEAR.get(word, CLOSENESS.get(word, RELATIONS.get(word, 0.0)))
    if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().lower().strip(",.;:!?()[]{}'\"-–—")
        if word == 'to' and previous in {'close', 'closest', 'next'}:
            value = 3.2
        elif word == 'of' and previous == 'front':
            value = 0.55
    return None, float(value)

programs.sol:
"""Approximate a co/ko spelling feature, strongest on the bare syllable.

The response fades in longer pieces, especially com/con/col/cou and cop/cov.
Kana/Korean ko and Cyrillic ко/со are secondary spelling responses.
A small set of joint/cooperation spellings gets weaker positive predictions.
The only context used is whether unspaced 'co' follows a letter in this document.
These rules average over word-specific strengths and omit unrelated responses.
"""
import unicodedata

READS = ()
SEPARATORS = ' \t\n\r_-./\\('
CO_EQUIVALENTS = {'こ': 3.9, 'コ': 3.9, '코': 2.9, 'ко': 1.6, 'со': 1.0}
# Chinese common/joint (共) and cooperative (协/協) forms.
COMMON_OR_COOPERATIVE = {
    '共': 4.5, '协': 2.6, '協': 2.6, '共同': 1.8, '共有': 1.8,
    '共和': 1.8, '协同': 1.8, '协调': 1.8, '协作': 1.8,
    '合作': 1.0, '協助': 1.0,
}


def extension(w):
    if w.startswith(('com', 'con')):
        return 0.0
    if len(w) == 3:
        if w[-1] in 'bt':
            return 2.6
        if w[-1] in 'pv':
            return 2.1
        return 1.1 if w[-1] in 'luw' else 1.7
    if w[2] in 'aeio':
        return {'a': 2.3, 'e': 1.7, 'i': 1.2, 'o': 1.7}[w[2]]
    if w.startswith(('col', 'cou', 'cop', 'cov')):
        return 1.6 if w.startswith('covid') else 0.2
    if w.startswith('cor'):
        if w.startswith('core'):
            return 1.2
        if w.startswith(('correc', 'corresp', 'corpor', 'corpus')):
            return 0.25
        return 0.8
    return 0.95 if w.startswith('cod') else 0.7


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.lstrip(SEPARATORS)
    w = raw.lower()
    folded = ''.join(c for c in unicodedata.normalize('NFD', w)
                     if not unicodedata.combining(c))
    value = 0.0
    if folded != w and folded.startswith('co'):
        value = 1.5 if folded == 'co' else 0.9
    elif w == 'co':
        value = 4.5 if raw.isupper() else 5.8 if token[:1].isspace() else 5.2
        if not raw.isupper() and token.startswith('.'):
            value = 6.0 if raw[0].isupper() else 8.5
        elif token == 'co':
            same_doc = (prefix.position > 0 and
                        prefix.document_ids[-1] == prefix.document_ids[-2])
            previous = prefix.token_strings[-2] if same_doc else ''
            value = 4.5 if previous[-1:].isalpha() else 6.1
    elif w.startswith('co'):
        value = extension(w)
    elif len(w) <= 5 and w.endswith('co'):
        value = 3.5 if len(w) == 3 and w[0] in 'ae' else 1.4
    elif w.startswith(('score', 'associ', 'joint')):
        value = 0.25 if w.startswith('association') else 0.9
    elif w in ('ko', 'cu', 'ço', 'iko'):
        value = 0.95
    elif w in CO_EQUIVALENTS:
        value = CO_EQUIVALENTS[w]
        if w in ('こ', 'コ') and token[:1].isspace():
            value = 2.1
    elif w in COMMON_OR_COOPERATIVE:
        value = COMMON_OR_COOPERATIVE[w]
    return None, float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:1285 - the "co" (together / joint) detector.

This component reads only the current token; it hardly depends on the context
around it. Its job is to respond to the prefix "co", the "together / with someone"
prefix that English and other languages use:

* strongest (about 5) on the bare token "co" in any casing or punctuation: "co-"
  as in "co-founder" or "co-local", "Co." as in a company name, " CO", "-co", ".co";
* moderately (about 1) on short English words that start with "co" and are not
  "col-", "cov-", "cop-", "cou-", "com-", "con-" or "cold": "code", "core", "cost",
  "coach", "coat", "cook", "coin", "cool", "cos", "coal";
* about 2 on "coordinate", "coordinates", "coordination";
* weakly (about 1.5) on "together" words: "joint", "jointly", "associate(d)",
  "colleague(s)", "cooperate", "collaborate", and the Chinese characters 协, 協, 共.

Everything else is 0. The program is stateless: it reads only the newest token,
drops punctuation and case, and returns a fixed value for each family.
"""

READS = ()

BARE_CO = 5.0    # the token "co" on its own
CO_WORD = 1.0    # short "co..." words: code, core, cost, coach, cook, coin ...
COORD = 2.0      # "coordinate", "coordinates", "coordination"
TOGETHER = 1.5   # joint / associate / colleague / cooperate / 协 協 共
NOT_CO_WORD = ("col", "cov", "cop", "cou", "com", "con", "cold")
TOGETHER_WORDS = {
    "joint", "jointly", "associate", "associated", "associates",
    "colleague", "colleagues",
}
TOGETHER_CHARS = set("协協共")


def letters(token):
    """The token's letters only, lower case: " Co." -> "co"."""
