COMMAS = ',，،'
STOPS = '.!?。！？;\n'


def attached_comma(token):
    """A comma merged with other text is generally weaker than a lone comma."""
    mark = next(c for c in token if c in COMMAS)
    before, after = token.split(mark, 1)
    if after:
        if '\n\n' in after:
            return -0.20
        if '\n' in after or any(c.isalpha() for c in after):
            return -0.04
        if all(c in '\"\'”’' for c in after):
            return -0.45
        return -0.05
    if before.isspace():
        return -0.77
    if mark != ',':
        return -1.10
    if before in (')', '$', '%', '`'):
        return -1.24
    if before.endswith('()'):
        return -0.49
    if before.strip() and all(c in ')]}' for c in before.strip()):
        return -0.45 if before.startswith(' ') else -0.84
    if '.' in before:
        return -0.22
    if '\\' in before or before.startswith(' '):
        return -0.25
    return -0.60


