    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, 0, 0, 0.0, 0, '', 0)
    _, distance, sentence, words, density, depth, previous, position = carry
    has_comma = any(c in token for c in COMMAS)

    if token == ',':
        value = (
            -2.03
            + 2.05 * exp(-distance / 3)
            + 0.79 * exp(-sentence / 4)
            + 0.32 * exp(-words / 8)
            + 0.18 * min(density, 4)
            - 0.37 * previous.startswith(' ')
            + 0.35 * previous.strip()[:1].isupper()
            + 0.33 * (depth > 0)
