READS = ()

COMMAS = {",", "，"}
CLOSERS = set(")]}\"'$")
SENTENCE_END = {".", "!", "?", "。", "！", "？"}
PEAK = -1.95  # typical activation of a comma that follows a long, comma-free stretch


def _gap_factor(gap):
    """Commas soon after the previous comma are weak (list-like)."""
    if gap < 5:
        return 0.25
    if gap < 10:
        return 0.75
    return 1.0


def _sentence_factor(since_start):
    """Commas that close a very short sentence opener are weak."""
    if since_start < 4:
        return 0.4
    if since_start < 8:
        return 0.7
    return 1.0


