    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    pos = prefix.position
    if carry is None or carry["doc"] != doc:
        # a new document (or the row's first token) resets the state
        carry = {"doc": doc, "start": pos, "last_comma": None, "last_break": None}

    value = 0.0
    if tok in COMMAS:
        gap = pos - carry["last_comma"] if carry["last_comma"] is not None else 999
        since = pos - carry["last_break"] if carry["last_break"] is not None else pos - carry["start"] + 1
        value = PEAK * _gap_factor(gap) * _sentence_factor(since)
        carry["last_comma"] = pos
    elif tok.endswith(",") and len(tok) > 1 and tok[-2] in CLOSERS:
        value = -1.0  # comma glued to a closing bracket or quote, e.g. "),"

    if tok.strip() in SENTENCE_END or "\n" in tok:
        carry["last_break"] = pos
    return carry, float(value)

