    if _has_hangul(token):
        if token.endswith(KOREAN_ENDINGS):
            return None, 4.5
        return None, 0.75
    if token in TOOL_HANDOFFS:
        return None, 1.10
    if token in {"<|im_start|>", "</tool_response>"}:
        return None, 0.45
    return None, 0.0

programs.sol:
"""Detect written nasal-plus-labial clusters, chiefly mp and mb.

Short fragments ending at the cluster give the strongest negative value.
The adjacent vowel sets its strength; preceding letters and a following
continuation dilute it. Simple inflections dilute it less. Example/import
are weak exceptions, whereas importance words retain a response.
Script aliases also recognize Cyrillic/Arabic m+p/b and Japanese/Thai
nasal-labial spellings. Adjacent-token joins receive a weaker response;
an exposed cluster has a small spillover onto its next word-internal token.
"""
READS = ()

# Nasals and labial stops, with nearby vowel/consonant spelling aliases.
ALIASES = str.maketrans({
    'м': 'm', 'п': 'p', 'б': 'b',
    'а': 'a', 'е': 'e', 'ё': 'e', 'и': 'i',
    'о': 'o', 'у': 'u', 'ы': 'y', 'к': 'k', 'т': 't',
    'م': 'm', 'ب': 'b', 'پ': 'p',
    'ン': 'm', 'ん': 'm', 'プ': 'p', 'ぷ': 'p',
    'ブ': 'b', 'ぶ': 'b',
    'ม': 'm', 'พ': 'p', 'ป': 'p', 'บ': 'b',
    'ä': 'e',
})

# Strength after each vowel: mp, mb. The last entry has no vowel.
VOWELS = {
    'a': (6.7, 4.4),
    'e': (3.7, 2.4),
    'i': (4.0, 2.4),
    'o': (3.3, 3.4),
    'u': (3.1, 1.6),
    'y': (3.9, 2.0),
    '': (3.6, 1.9),
}


def spelling(token):
    word = token.strip().lower().translate(ALIASES)
    j, kind = word.find('mp'), 0
    if j < 0:
        j, kind = word.find('mb'), 1
    if j < 0 or 'example' in word or word in {
        'import', 'imports', 'imported', 'importing',
    }:
        return 0.0
    if word.startswith(('important', 'importance')):
        return -0.8 if word.startswith('importance') else -1.2

    vowel = word[j - 1] if j and word[j - 1] in VOWELS else ''
    before = word[:j - bool(vowel)]
    strength = VOWELS[vowel][kind]
    if before:
        strength *= (0.72, 0.50, 0.19)[min(3, len(before)) - 1]
        if not vowel:
            strength *= 0.8
    if before in ('c', 'k') and vowel == 'o':
        strength *= 0.47
    if before == 't' and vowel == 'e':
        strength *= 0.77

    tail = word[j + 2:]
    if tail == 's':
        strength *= 0.76
    elif tail in ('ed', 'ing'):
        strength *= 0.60
    elif tail:
        strength *= 0.97 if tail.startswith('b') else 0.35 / len(tail) ** 0.47
    if token.startswith((' ', '\t')):
        strength *= 0.89 if vowel else 0.63
    elif not vowel and token.strip().isupper():
        strength *= 0.82
    return -float(strength)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, old_value = '', 0.0
    else:
        previous, old_value = carry[1:]
    base = value = spelling(token)
    joined = token.lower().translate(ALIASES)
    if token and token[0].isalpha():
        if previous.endswith('m') and joined[0] in 'pb':
            value -= 1.3 / (1 + 0.12 * (len(token) - 1))
        elif previous.endswith(('mp', 'mb')):
            value -= 0.12 * abs(old_value)
    return (doc, joined, base), float(value)

"""Approximate a response to English specifications and reformulations.
The numerical strengths were estimated from training examples.

'Given/described by' and 'expressed/written as' get large negative values;
'can be' strengthens them. Method/source linkers ('using', 'from', 'via')
are weaker versions of the same pattern. Ordinary passives are weaker. Short
active phrases ('write it as'), selected approximation/math words, and the
prefix 'real-val' are handled too. Publication,
repeated-step and comparison phrases have small positive values. Unrecognized
text gets zero. A bounded text tail is reset for each packed document.
"""
import re

READS = ()

# Semantic verb classes, with strengths on 'by' and 'as', respectively.
VERBS = (
    ('given described defined explained', -2.8, -1.35),  # specification
    ('expressed represented', -2.45, -1.45),  # representation
    ('written rewritten', -0.9, -1.2),  # written reformulation
    ('determined characterized characterised', -2.12, -0.65),  # characterization
    ('calculated computed measured estimated approximated specified', -1.53, -0.72),
    ('indicated shown proven proved demonstrated confirmed identified '
     'realized understood illustrated found', -1.4, -0.57),  # evidence
    ('governed constrained related denoted modeled distinguished '
     'depicted exemplified formulated outlined implemented analyzed classified '
     'evaluated inferred summarized simulated scaled spanned', -1.48, -0.62),
    ('achieved accomplished attained obtained', -1.2, -0.52),  # attainment
    ('created formed induced derived controlled enclosed caused mediated captured',
     -1.04, -0.44),  # formation/causation
    ('published posted uploaded released issued', 0.64, -0.05),  # publication
)
VERBS = tuple((set(words.split()), by, as_) for words, by, as_ in VERBS)
METHOD_LINKERS = {' from': 0.24, ' using': 0.22, ' via': 0.35,
                  ' with': 0.13, ' through': 0.19}
MODAL = re.compile(r'\b(can|cannot|can.t|could|may|might)\b'
                   r'[^.!?\n]{0,30}\bbe\s*$', re.I)
ACTIVE = re.compile(
    r'\b(describe[sd]?|defin(?:e[sd]?|ing)|express|represent|'
    r'write|wrote|denote|mean|specify|calculate)\b([^,.!?;:\n]{0,35})$', re.I)


def last_word(text):
    return re.search(r'([A-Za-z]+)\s*$', text)


def response(s, tail):
    if s in METHOD_LINKERS:
        m = last_word(tail)
        if m and any(m[1].lower() in words for words, _, _ in VERBS):
            return METHOD_LINKERS[s] * response(' by', tail)
        return -0.12 if s == ' via' else 0.0
    if s in (' by', ' as'):
        by = s == ' by'
        m = last_word(tail)
        previous = m[1].lower() if m else ''
        head = previous
        before = tail[:m.start()] if m else ''
        if previous.endswith('ly') or previous in {'not', 'only', 'above', 'below'}:
            m = last_word(before)
            if m:
                head, before = m[1].lower(), before[:m.start()]
        for words, by_value, as_value in VERBS:
            if head in words:
                value = by_value if by else as_value
                modal = MODAL.search(before)
                if modal and value < -0.4:
                    value -= 0.82 if modal[1].lower().startswith('can') else 0.3
                return value
        if by and previous in {'step', 'side', 'required', 'taken'}:
            return 0.66 if previous == 'required' else 0.4
        active = ACTIVE.search(tail)
        if active:
            verb, obj = active[1].lower(), active[2].lower()
            blocked = re.search(r'\b(as|by|is|are|was|were|be|that|which|who|to)\b', obj)
            if not blocked and len(obj.split()) <= 4 and verb != 'mean':
                if not by or verb not in {'write', 'wrote', 'express'}:
                    value = -1.25 if by else -1.0
                    if verb == 'described':
                        value = -0.6
                    if re.search(r'\bcan\b[^.!?\n]{0,20}$', tail[:active.start()], re.I):
                        value -= 0.3
                    return value
            if verb == 'mean' and by and not obj.strip():
                return -1.4
        if not by and previous in {'serve', 'serves', 'served', 'much', 'many',
                                  'far', 'soon', 'long', 'early', 'well'}:
            return 0.1
        if previous in {'known', 'made', 'held', 'seen', 'built', 'done', 'driven', 'led'}:
            return -0.7 if by else -0.4
        if previous.endswith('ed'):
            return -0.42 if by else -0.27
        if previous in {'is', 'be', 'are', 'was', 'were'}:
            return -0.55 if by else -0.27
        return -0.12 if by else -0.03
    if s.strip().isalpha():
        m = re.search(r'([A-Za-z]+)$', tail + s)
        word = m[1].lower() if m else ''
        if word == 'approximately':
            return -0.93
        if word in {'roughly', 'crudely', 'mathematically', 'geometrically'}:
            return -0.6
        if word in {'simply', 'precisely', 'exactly'}:
            return -0.12
    if s == '-val' and re.search(r'\breal$', tail):
        return -1.35
    if s in (' written', ' expressed', ' described', ' represented', ' explained'):
        if MODAL.search(tail):
            return -0.95 if s in (' written', ' expressed', ' described') else -0.55
        return -0.06
    if s == ' say':
        if re.search(r'\b(can|cannot|can.t)\s*$', tail):
            return -0.9
        return -0.5 if re.search(r'\b(could|might)\s*$', tail) else -0.1
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    return (doc, (tail + s)[-160:]), float(response(s, tail))

programs.haiku:
"""Activation of layer-0 MLP unit 1297, a negative "explaining-relation" detector.

It goes strongly negative on the word "by" or "as" when it introduces how something is
defined, described, determined or expressed: "described by", "given by", "defined as",
"expressed as", "written as", "determined by", "can be written as". It is weaker
negative after other passive verbs ("caused by", "formed by", "created by"), and mildly
negative on hedges such as "approximately" and "roughly". It is positive on "by" after
verbs of publishing, requiring or using ("published by", "required by", "adopted by",
"step by step", "side by side", "multiplied by"). Other "by" is slightly negative, and
everything else is near zero. Values are typical activations, in the units of the
component's own activation (fit on about 5,000 training rows)."""

READS = ()

DESCRIBE = {"described", "given", "defined", "explained", "expressed", "represented",
            "characterized", "determined", "indicated", "calculated", "identified",
            "measured", "shown", "demonstrated", "derived", "written", "depicted",
            "interpreted", "computed", "understood", "presented", "termed", "viewed",
            "estimated", "specified", "obtained", "achieved", "constrained", "governed"}
EXPRESS = {"expressed", "written", "represented", "defined", "described"}
PUBLISH = {"published", "required", "adopted", "released", "posted", "issued", "taken",
           "used", "approved", "accepted", "sponsored", "drafted", "step", "side", "sides",
           "absorbed", "employed", "considered", "multiply", "divide"}
AUX = {"is", "are", "was", "were", "be", "been", "being", "can", "may", "must", "will",
       "would", "could", "should", "am"}
HEDGES = {"approximately", "roughly"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    n = len(prefix)
    same_doc = n > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    before = [s.strip() for s in prefix.token_strings[max(0, n - 4):n - 2]]
    aux = any(w in AUX for w in before)
    value = 0.0
    if word == "by":
        if prev in DESCRIBE:
            value = -2.4 if aux else -1.8
        elif prev in PUBLISH:
            value = 0.5
        elif prev.endswith("ed"):
            value = -0.5
        else:
            value = -0.2
    elif word == "as":
        if prev in EXPRESS:
            value = -1.75 if aux else -1.35
        elif prev in DESCRIBE:
            value = -0.5 if aux else -0.1
    elif word in HEDGES:
        value = -0.9
    return carry, value

programs.luna:
"""Approximate activations from a few relation and approximation words.

The component is usually quiet. It has a small negative average on “by”
and “as,” and stronger negative examples on rough estimates.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if word == " by":
        return None, -0.38
    if word == " as":
        return None, -0.06
    if word == " approximately":
        return None, -0.85
    if word == " roughly":
        return None, -0.62
    return None, 0.0

programs.haiku:
"""Component layers.0.mlp.down_proj:1299: a "difference / otherness" word detector.

The component is almost always silent (about 0). It goes strongly negative on the
word that says two things are different, other, or the same, and only on that word:

  * "different" (and "Different", "_different"): about -7.5, by far the largest;
  * "differently": about -5; "differ", "differs", "differed", "differentiate": about -2.5;
  * "different" in other languages ("不同", "khác", "разных", "verschiedene", "다른",
    "différent", "diferentes", "違う", ...): about -4; weaker words for the same idea
    ("差", "同", "異", "相同", "anders", ...): about -1;
  * "difference", "diff", "differential": about -1.4;
  * "same", "other", "various", "similar", "opposite", "distinct", "separate": about -1.

The value depends on the word alone, not on the context around it. Words that
merely look alike ("difficult", "diffusion", "another", "others") stay at 0.

Main program: `step` looks up the newest token's word (lower-cased, spaces removed)
in these lists and returns the matching value. It has no state across positions.
"""

READS: tuple[str, ...] = ()   # reads no other component

DIFFERENT = -7.5          # "different" itself
DIFFERENTLY = -5.0
DIFFER = -2.5             # any other form of "differ"
TRANSLATED = -4.0         # "different" in another language
WEAK_TRANSLATED = -1.0    # weaker words for "difference / same / other" abroad
DIFFERENCE = -1.4         # difference, diff, differential
OTHER = -1.0              # same, other, various, similar, ...

TRANSLATED_DIFFERENT = {
    "不同", "不同的", "的不同", "有不同的", "不一样", "不一样的", "khác", "разных",
    "различные", "различных", "verschieden", "verschiedenen", "verschiedene",
    "verschill", "다른", "다르", "différent", "différents", "diferentes", "diferente",
    "違う", "المختلفة",
}
WEAK_TRANSLATED_WORDS = {
    "差", "差异", "差别", "同", "异", "異", "相同", "同じ", "違い", "区别", "色々",
    "様々な", "다양한", "anders", "отлич",
}
DIFFERENCE_WORDS = {"difference", "differences", "diff", "differential"}
OTHER_WORDS = {
    "same", "other", "various", "similar", "opposite", "distinct", "separate",
    "contrary", "unlike", "contrast",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "differently":
        value = DIFFERENTLY
    elif word in DIFFERENCE_WORDS or word.startswith("indiffer"):
        value = DIFFERENCE
    elif word.startswith("differentiat"):
        value = DIFFER
    elif "different" in word:
        value = DIFFERENT
    elif word.startswith("differ"):
        value = DIFFER
    elif word in TRANSLATED_DIFFERENT:
        value = TRANSLATED
    elif word in OTHER_WORDS:
        value = OTHER
    elif word in WEAK_TRANSLATED_WORDS:
        value = WEAK_TRANSLATED
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Approximate a rare negative response to difference, sameness, and alternatives."""
READS = ()

# Whole-word cues are kept small to avoid treating every similar-looking word
# as a comparison. Punctuation around a token does not change its word.
DIFFERENCE_WORDS = {
    "different", "differs", "difference", "differences", "differently",
    "differing", "differed", "differential", "différent",
}
COMPARISON_WORDS = {
    "same", "other", "others", "another", "various", "variety",
    "similar", "similarly", "distinct", "separate", "opposite",
    "varying", "varied", "vary", "alternative", "alternatives",
    "unlike", "contrast", "contrasting", "else",
}
EDGE_PUNCTUATION = ".,:;!?()[]{}-"

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().strip(EDGE_PUNCTUATION)
    if word in DIFFERENCE_WORDS:
        return None, -3.0
    if word in COMPARISON_WORDS:
