programs.sol:
"""A lexical detector for representing, reflecting, and standing for something.

Predict a strong negative response to 'represent' and 代表, a weaker one to
related words and political terms, plus suffixes and grammatical partners.
It deliberately leaves unrelated, idiosyncratic token responses unexplained.
"""
READS = ()

RELATED_WORDS = set('''
indicate indicates indicating indicative
signify signifies signifying
constitute constitutes constituted constituting
resemble resembles resembled resembling
embody embodies embodied embodying
depict depicts depicted depicting
portray portrays portrayed portraying portrayal
'''.split())
# These mean indicate/display, reflect, symbolize, embody, or substitute.
DISPLAY_WORDS = {'表示', '反映', '象征', '象徵', '体现', '體現',
                 '代', '示', 'แสดง'}
REPRESENT_LINKS = {'a': -1.2, 'an': -0.85, 'the': -0.67,
                   'by': -0.8, 'as': -0.3, 'in': -0.3}


def response(word):
    if word.startswith('represent'):
        if 'ation' in word:
            return 'noun', -1.6 if word.endswith('s') else -2.0
        if 'ative' in word:
            return 'agent', -3.2
        if word == 'represented':
            return 'represent', -3.5
        return 'represent', -4.3 if word == 'representing' else -4.0
    if word in {'rep', 'repr'}:
        return 'abbreviation', -1.3
    # French and Russian stems for representing/presenting.
    if word.startswith('représ'):
        return 'stem', -2.5
    if word.startswith('представ'):
        return 'stem', -1.25
    # 代表 means represent/delegate; 不 marks negation.
    if word == '代表':
        return 'cjk', -6.9
    if word in {'代表着', '代表著', '人大代表', '为代表'}:
        return 'cjk', -6.0
    if word in {'不代表', '并不代表'}:
        return 'cjk', -4.2
    if word in {'代表性', '为代表的', '代表大会', '代表团'}:
        return 'cjk', -3.0
    if word in DISPLAY_WORDS:
        return '', -1.2
    if word.startswith('reflect'):
        if word.startswith('reflection'):
            return 'noun', -0.7
        return 'related', -1.0 if word == 'reflected' else -1.7
    if word.startswith('correspond'):
        return 'correspond', -0.3 if word == 'correspondence' else -0.65
    if word in RELATED_WORDS:
        return 'related', -0.9
    if word == 'indicated':
        return 'related', -0.35
    if word in {'denote', 'denotes', 'denoted', 'denoting'}:
        return 'related', -0.5
    if word in {'parliament', 'parliamentary', 'republic', 'trustee', 'trustees'}:
        return 'political', -0.7
    if word in {'congressman', 'congresswoman'}:
        return 'political', -1.7
    if word == 'behalf':
        return 'behalf', -1.7
    return '', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('._/').lower()
    kind, value = response(word)
    if carry is not None and carry[0] == doc and value == 0.0:
        _, family, strength = carry
        if family == 'represent':
            value = REPRESENT_LINKS.get(word, 0.0)
        elif family == 'correspond' and word == 'to':
            value = -1.0
        elif family in {'noun', 'agent'} and word == 'of':
            value = strength * (0.85 if family == 'noun' else 0.6)
        elif family == 'behalf' and word == 'of':
            value = -0.85
        elif family == 'political' and word == 'of':
            value = -0.6
        elif (family == 'related'
              and word in {'a', 'an', 'the', 'of', 'by', 'in', 'that'}):
            value = strength * 0.2
        elif family == 'cjk' and word in {'了', '着', '著'}:
            value = strength * 0.45
        if family and raw and raw[0].isalpha():
            if family == 'abbreviation' and word == 'resents':
                kind, value = 'represent', -4.5
            elif word in {'ative', 'atives'}:
                kind, value = 'agent', strength * 0.8
            elif word in {'ing', 'ed'}:
                kind, value = family, strength * 0.8
            elif word in {'ation', 'ations'}:
                kind, value = 'noun', strength * 0.5
    return (doc, kind, value if kind else 0.0), float(value)

programs.haiku:
"""Fires on the word just before a bare (dictionary-form) verb is expected next.

Strongest: "let's" and "let me"; modal verbs (could, may, can, might, should, will,
must, would); infinitive "to" after words like "able", "unable", "need", "want", "how";
"how" itself; Chinese ability/modal words (如何, 无法, 可以, 能, 需要).
Weak or negative: "to" as a preposition ("according to", "due to", "contribute to");
"'s" as a possessive (children's). Everything else is 0.
"""

READS = ()

MODALS = {"can": 0.9, "could": 1.4, "may": 1.3, "might": 1.0, "must": 0.7,
          "should": 0.9, "will": 0.8, "would": 0.6, "shall": 1.1, "cannot": 0.7,
          "'ll": 1.5, "’ll": 1.5}
CONTRACTIONS = {"'m", "'re", "'ve"}          # I'm, you're, we've: about 0.8
PRONOUN_IS = {"it", "that", "there", "here", "what", "he", "she", "who", "where"}
PREP_TO = {"according", "due", "leading", "related", "relate", "return", "compared",
           "similar", "referred", "applied", "convert", "contribute", "contributes",
           "contribution", "respect", "prior", "addition", "corresponds", "corresponding",
           "close", "closest", "equal", "subject", "lead", "leads", "added", "connected"}
TO_LICENSERS = {"able", "unable", "need", "needs", "needed", "want", "wants", "wanted",
                "how", "ability", "try", "trying", "attempt", "decided", "way", "ways",
                "difficult", "hard", "easy", "possible", "opportunity", "order", "required"}
CHINESE = {"如何": 3.0, "无法": 2.5, "不能": 1.5, "能够": 2.5, "能": 1.0, "可以": 1.3,
           "需要": 0.8, "怎么": 2.0, "要": 0.7, "才能": 2.9}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    cur = _word(raw)
    if cur in ("able", "unable") and raw[:1] != " ":
        return carry, 0.0  # "able" glued into an identifier, as in target_able
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    if cur in MODALS:
        value = MODALS[cur]
    elif cur in CHINESE:
        value = CHINESE[cur]
    elif cur == "to":
        if prev in PREP_TO:
            value = -0.2
        elif prev in TO_LICENSERS:
            value = 1.6
        else:
            value = 0.5
    elif cur == "me" and prev == "let":
        value = 1.8
    elif cur in ("'s", "’s"):
        if prev == "let":
            value = 2.9
        elif prev in PRONOUN_IS:
            value = 0.85
        else:
            value = 0.0
    elif cur in CONTRACTIONS:
        value = 0.8
    elif cur in ("how", "please", "able", "unable"):
        value = 1.0
    else:
        value = 0.0
    return carry, float(value)

