Spatial partitives and a few place/time words give small positive responses.
Thinking tags are handled separately. Unrecognized tokens return zero.
"""
READS = ()
CARDINAL = {'north', 'south', 'east', 'west'}
DIRECTIONS = CARDINAL | {a + b for a in ('north', 'south') for b in ('east', 'west')}
ADJECTIVES = {d + 'ern' for d in DIRECTIONS}
POSITIONS = {
    'central': -0.29, 'upper': -0.28, 'lower': -0.06,
    'inner': -0.20, 'outer': -0.17, 'interior': -0.06,
}
PLACES = {'river', 'lake', 'sea', 'ocean', 'coast', 'beach', 'city', 'area', 'province'}
GEO_CUES = PLACES | {
    'climate', 'habitat', 'tropical', 'temperate', 'forest', 'species',
    'mountain', 'mountains', 'endemic', 'located', 'situated',
}
PARTS = {'part', 'portion', 'half', 'side', 'front', 'back', 'bottom', 'surface'}
CHINESE_REGIONS = {a + b for a in '东西南北' for b in ('部', '方')} | {'中部', '中央'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before, age = ('', '', 100) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    capital = token.strip()[:1].isupper()
    whole = token[:1].isspace() or not previous
    definite = previous in {'the', 'its', 'their'}
    locative = previous in {'in', 'within', 'between'} or (
        previous == 'the' and before in {'in', 'within'}
    )
    geographic = age <= 8
    value = 0.0
    if word in ADJECTIVES:
        value = -0.52 if capital else -0.76
        value -= 0.18 if locative else (0.14 if definite else 0.0)
        if not whole:
            value *= 0.6
    elif not whole and (previous.lstrip('-') + word in ADJECTIVES
                        or before + previous + word in ADJECTIVES):
        value = -0.55
    elif word in POSITIONS:
        value = POSITIONS[word]
        if word == 'central':
            value = -0.60 if locative or geographic else (-0.40 if definite else value)
            value -= 0.10 * capital
        else:
            value -= 0.10 * definite + 0.16 * locative + 0.10 * geographic
            if not whole:
                value *= 0.4
    elif word in {'temper', 'subt', 'mont', 'equ'} and whole and not capital:
        value = -0.80 if geographic else (-0.10 if word == 'mont' else -0.23)
    elif word == 'dry':
        value = -0.30 if definite or locative else -0.14
        value -= 0.12 * geographic
    elif word in {'late', 'mid', 'greater', 'lesser', 'great'} and whole:
        value = -0.36 if locative else (-0.24 if definite else -0.08)
    elif word in {'part', 'parts', 'most'} and previous in ADJECTIVES:
        value = -0.80 if word == 'parts' else -0.45
    elif word == 'of' and previous in PARTS:
        value = 0.10
    elif word in {'tropical', 'inland', 'mainland', '-central', 'footh'}:
        value = -0.65 if word in {'-central', 'footh'} else -0.30
    elif word in CHINESE_REGIONS:
        value = -0.33
    elif word == 'administrative':
        value = -0.05 if capital else -0.18
    elif word in {'mountain', 'mountains'}:
        value = -0.12
    elif word in PLACES:
        value = 0.06
    elif word in {'later', 'earlier', 'next', 'subsequent', 'past'}:
        value = 0.15 if word == 'later' else 0.06
    elif word in {'<think>', '</think>'}:
        value = 0.13 if word == '<think>' else 0.28
    age = 0 if word in GEO_CUES else min(100, age + 1)
    return (doc, word, previous, age), value

programs.haiku:
"""Region-adjective detector (v5): words that say where within a larger region something lies,
plus the noun that follows such a word ("southern part"), and the end-of-thinking tag."""
READS = ()

COMPASS = {"western", "eastern", "northern", "southern", "northeastern",
           "southeastern", "southwestern", "northwestern"}
POSITION = {"central", "upper", "inner", "outer"}
PLACE = {"lower", "mid", "late", "middle", "north", "east", "south", "tropical", "inland",
         "subtropical", "arctic", "remote", "great", "greater", "administrative",
         "asian", "british", "european", "pacific", "atlantic", "caribbean", "dry"}
PART = {"part", "parts"}


def value_of(word):
    word = word.strip()
    lower = word.lower()
    capital = word[:1].isupper()
    if lower in COMPASS:
        return -0.55 if capital else -0.9
    if lower in POSITION:
        return -0.45 if capital else -0.35
    if lower in PLACE:
        return -0.15
    if word == "</think>":
        return 0.28
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word.lower() in PART and len(prefix.token_strings) > 1:
        before = prefix.token_strings[-2].strip().lower()
        if before in COMPASS or before in POSITION:
            return None, -0.3
    return None, value_of(prefix.token_strings[-1])

programs.luna:
"""Flag compass, regional, terrain, and climate descriptors with a negative response."""

READS = ()

COMPASS_AND_REGION = {
    "north", "northern", "northeast", "northeastern", "northwest",
    "northwestern", "south", "southern", "southeast", "southeastern",
    "southwest", "southwestern", "east", "eastern", "west", "western",
    "central", "midwestern", "interior", "upper", "lower", "greater",
    "lesser", "tibetan", "中央",
}
LANDSCAPE_AND_CLIMATE = {
    "temperate", "montane", "subtropical", "subtropics", "dry",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower().lstrip("-")
    if word in COMPASS_AND_REGION or word in LANDSCAPE_AND_CLIMATE:
        return None, -0.2
    return None, 0.0

programs.sol:
"""Approximate code type modifiers, operators, and opening delimiters.

Stars and ampersands have larger responses after type-like names, especially
C/C++ primitive types or const-qualified names. Numeric type-width suffixes
and vector dimensions also respond. Empty array brackets, generic
type closers, namespace separators and opening braces also respond. The last
200 characters help distinguish these from prose, markup and TeX. Ordinary
text gets a small baseline. Negative estimates cover typedef, quoted brackets
and TeX argument braces. State resets at each packed-document boundary.
"""
import re

READS = ()
NUMERIC = set('int uint long ulong short ushort float double bool boolean '
              'byte sbyte signed unsigned decimal usize isize size_t ssize_t'.split())
CHAR_OR_VOID = set('char wchar_t char16_t char32_t void FILE'.split())
OBJECT = set('string object String Object Boolean Integer Long Double Float '
             'Character Byte Short'.split())
STREAM = set('ostream istream ofstream ifstream fstream iostream'.split())
CODE = re.compile(
    r'#include|->|::|\b(?:const|struct|typedef|void|unsigned|int|char|float|'
    r'double|class|public|private|static|new|func|fn)\b'
)
WIDTH = re.compile(
    r'(u?int|UInt|Int|float|Float|vec|Vec|Vector|FVector|BVec)(\d*)$'
)
WORD = re.compile(r'([A-Za-z_][A-Za-z_0-9]*)[ \t]*$')


def response(token, tail):
    s = token.strip()
    if s.isascii() and s.isdigit():
        m = WIDTH.search(tail)
        if not m:
            return 0.001
        family = m[1].lower()
        unsigned = family.startswith('u')
        if m[2]:
            return 1.0 if unsigned else (0.25 if family == 'float' else 0.4)
        if 'vec' in family:
            return 2.1 if s in ('2', '3') else 1.0
        if s == '3':
            return 2.4 if unsigned else 1.4
        return 1.3 if unsigned else 0.7
    namespace_type = s in OBJECT and tail.endswith('::')
    if not any(c in s for c in '*&[]{}<>|') and not namespace_type and s not in (
        '::', '::~', '_t', '_ptr', '_ref', '_iterator', 'Ref', 'Reference',
        'Iterator', 'Iter', 'Ptr', 'Pointer', 'mut', 'ref', 'reference', 'typedef',
    ):
        return 0.001
    m = WORD.search(tail)
    word = m[1] if m else ''
    numeric = word in NUMERIC or bool(
        re.fullmatch(r'(?:u?int|float)\d+(_t)?', word)
    )
    primitive = numeric or word in CHAR_OR_VOID or word in OBJECT
    capital = bool(word and word[0].isupper())
    code = bool(CODE.search(tail))
    tight = bool(tail and not tail[-1].isspace() and not token[0].isspace())

    # Pointer/reference declarations versus multiplication and conjunction.
    if s in ('*', '**', '&'):
        ref = s == '&'
        if s == '**' and re.search(r'\b(?:def|lambda|self)\b|np\.', tail):
            return 1.3
        if '\n' in token or not word and not tail.rsplit('\n', 1)[-1].strip():
            return 0.05
        if re.search(r'\[\*[^]]*$', tail):
            return 0.05
        if ref and re.search(r'\bconst\s+[\w:<>]+\s*$', tail):
            return 5.2
        if word in CHAR_OR_VOID:
            return 4.6 if ref else (4.7 if s == '**' else 6.5)
        if numeric:
            return 4.3 if ref else 4.0
        if word.endswith(('_t', '_type')) or word in STREAM:
            return 4.0
        if ref and word == 'const':
            return 5.5
        product = m and tail[:m.start()].rstrip().endswith('*')
        if not ref and capital and code and product:
            return 1.5
        if capital and code:
            return 1.5 if ref else 3.3
        if '_' in word and code:
            return 1.9 if ref else 3.7
        if s == '**':
            return 0.05
        if code and word:
            return 1.0 if ref else 1.9
        if not ref and code:
            return 1.0
        return 0.16 if ref else 0.3
    if s in ('*&,', '*&', '*)&', '*>&'):
        return 3.0
    if s in ('*)', '*,', '*>', '*>(', '*>,', '&)', '&,'):
        return 2.0 if primitive or code else 0.5
    if s in ('(&', '&[', '&_', ',&', '\",&'):
        return 1.2 if code else 0.5
    if s == '>&':
        return 0.7

    # Array and generic type notation.
    if re.fullmatch(r'(?:\[,*\])+', s):
        if primitive:
            return 4.3 if tight else 2.5
        if capital and code:
            return 2.3 if tight else 1.2
        return 1.5 if code and word else 0.55
    if re.fullmatch(r'(?:\[,*\])+[>{},*]', s):
        return 1.9
    if s == '<?>':
        return 1.7
    if s in ('>', '>>', '>>,'):
        if '\n' in token:
            return 0.0
        generic = bool(re.search(r'[A-Za-z_0-9:]<[^<>\n]{0,100}$', tail))
        if primitive and (code or generic):
            return 2.1
        if capital and generic:
            return 1.4 if s == '>' else 0.7
        return 0.02
    if s in ('::', '::~'):
        if token[0].isspace():
            return -0.2
        if s == '::~':
            return 3.1
        if word == 'std' or word in OBJECT or word in STREAM:
            return 1.6
        declaration = re.search(
            r'\b(?:int|void|bool|float|double|char|\w+_t)\s+\w+\s*$', tail
        )
        return 1.7 if declaration else 0.6
    if s == '->':
        return 0.65 if not token[0].isspace() else 0.0
    if s in ('&&', '||'):
        return 0.65 if token[0].isspace() else 0.4

    # Block opening versus a TeX argument or a quoted object key.
    if '{' in s and all(c in '(){=+\\' for c in s):
        if re.search(r'\\[A-Za-z]+\s*$', tail):
            return -0.16
        if '\n' in token:
            return 0.75
        return 0.55 if token[0].isspace() or s != '{' else 0.2
    if s.startswith(('["', "['")):
        return -0.25
    if s == '}' and re.search(r'@(?:type|param|returns?).*\{[^}]*$', tail):
        return 1.2
    if s == ']' and re.search(r'\[[A-Z]\w*$', tail):
        return 1.2
    if s == '[':
        return 0.19 if tight else 0.0
    if s == '<':
        if tight and capital and code:
            return 0.8
        return 0.15 if tight else -0.05
    if s in OBJECT and tail.endswith('::'):
        return 1.2
    if s == '_t':
        type_name = capital and len(word) > 1 or bool(
            re.fullmatch(r'u?int\d+|size|ssize|time|ptrdiff|pthread|wchar', word)
        )
        if re.fullmatch(r'u?int\d+', word):
            return 2.3
        return 1.7 if type_name else 0.2
    if s in ('_ptr', '_ref', '_iterator'):
        return 1.0
    if s in ('Ref', 'Reference', 'Iterator', 'Iter', 'Ptr', 'Pointer'):
        if tight and capital and code:
            return 1.8
        return 1.1 if tight else 0.05
    if s == 'mut':
        return 1.6 if tail.rstrip().endswith('let') else 0.6
    if s in ('ref', 'reference'):
        return 0.3 if token[0].isspace() else (0.2 if code else 0.0)
    if s == 'typedef':
        return -2.0
    return 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (tail + token)[-200:]), float(response(token, tail))

"""An early-context, prose-resumption approximation.

English grammatical words get the largest negative predictions after numeric,
punctuation or whitespace gaps, especially capitalized openings. A short gap
trace extends the response into following tokens. The response fades as more
alphabetic tokens accumulate; small token-class background values remain.
The first token uses simple class offsets. All state resets per document.
This explains a contextual tendency, not the component's full lexical variation.
"""
READS = ()

# Pronouns/determiners, helping verbs, prepositions, conjunctions, and common
# question/discourse openings are familiar grammatical classes, not token IDs.
GRAMMAR = {
    'article_the': 'the',
    'articles_a_an': 'a an',
    'pronouns_determiners': (
        'all another any both each enough every few he her him his i it its '
        'itself less many me more most much my myself no other our ourselves '
        'several she some that their them themselves these they this those '
        'us we you your yourself'
    ),
    'copulas_modals': (
        'are be been being can could did do does had has have is may might '
        'must shall should was were will would'
    ),
    'prepositions': (
        'about after among at before between by during following for from in '
        'into of on over since through to under until upon with within '
        'without'
    ),
    'conjunctions': (
        'although and as because but if or since so than unless whether '
        'while'
    ),
    'clause_openers': (
        'according alternatively assuming concerning considering depending '
        'furthermore given hence here how however instead let meanwhile '
        'moreover nevertheless now please regarding suppose then there '
        'therefore thus what when where which who why'
    ),
}
GRAMMAR = {name: frozenset(words.split()) for name, words in GRAMMAR.items()}
CONTRACTIONS = frozenset(("'s", "’s", "'re", "'ve", "'ll", "'d", "n't"))

# Fitted on training text: background, early-context slope,
# numeric-document-start slope,
# leading-space slope, recent-gap slope: one row per named class.
WEIGHTS = {
    'conjunctions': (0.012, 0.113, -0.118, -0.069, -0.552),
    'contraction': (0.007, -0.249, -0.034, 0.0, -0.184),
    'article_the': (0.006, 0.217, -0.237, -0.202, -0.935),
    'clause_openers': (0.003, -0.116, -0.049, -0.144, -0.543),
    'copulas_modals': (0.018, -0.04, -0.135, -0.453, -0.582),
    'articles_a_an': (0.025, 0.103, -0.021, -0.309, -0.51),
    'markup': (-0.048, 0.051, -0.095, 0.001, -0.043),
    'numbers': (0.001, 0.094, 0.002, 0.0, -0.133),
    'prepositions': (-0.002, 0.071, -0.142, -0.092, -0.594),
    'punctuation': (-0.003, 0.118, -0.101, -0.019, -0.258),
    'pronouns_determiners': (0.011, 0.03, -0.123, -0.247, -0.449),
    'whitespace': (0.008, 0.099, -0.09, 0.066, -0.275),
    'word': (0.001, 0.055, -0.058, -0.136, -0.242),
}

def classify(s):
    word = s.strip()
    if word in CONTRACTIONS:
        return 'contraction', False
    if word.startswith('<') and word.endswith('>'):
        return 'markup', False
    if s.isspace():
        return 'whitespace', False
    if word.isdigit():
        return 'numbers', False
    if (word.isascii() and word.isalpha()
            and not (len(word) > 1 and word.isupper())):
        for name, words in GRAMMAR.items():
            if word.lower() in words:
                return name, word[0].isupper()
    if word and all(not c.isalnum() for c in word):
        return 'punctuation', False
    return 'word', False

def gap_strength(s):
    if s.startswith('<|'):
        return 0.0
    if '\n' in s:
        return 1.6
    if s.isspace():
        return 1.3
    if any(c.isalpha() for c in s):
        return 0.0
    if s.strip().isdigit():
        return .8
    s = s.rstrip()
    if s.endswith(('.', '?', '!')):
        return 1.7
    if s.endswith((',', ':', ';')):
        return 1.5
    if s.endswith((')', ']', '}')):
        return 1.0
    return .5

def initial_value(group, capital):
    if capital and group in {'article_the', 'articles_a_an'}:
        return .21
    if capital and group == 'clause_openers':
        return .10
    if group in {'numbers', 'punctuation', 'markup'}:
        return .08
    if not capital and group == 'copulas_modals':
        return -.12
    return .01

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, alphabetic_tokens, trace = 0, 0, 0.0
        first_number = s.strip().isdigit()
    else:
        _, age, alphabetic_tokens, first_number, trace = carry
    group, capital = classify(s)
    if age == 0:
        value = initial_value(group, capital)
    else:
        base, early, number, leading, gap = WEIGHTS[group]
        fade = (1 + (alphabetic_tokens + .15 * age) / 25) ** -2
        has_space = bool(s) and s[0].isspace()
        value = base + fade * (
            early + number * first_number + leading * has_space + gap * trace)
        if capital:
            value += .025 - fade * (.054 + .077 * has_space + .207 * trace)
    alphabetic_tokens += any(c.isalpha() for c in s) and not s.startswith('<')
    trace = gap_strength(s) + .25 * trace
    state = (doc, age + 1, alphabetic_tokens, first_number, trace)
    return state, float(value)

programs.haiku:
"""Early-in-document sentence openers (layer-0 MLP unit 1315, down_proj).

What it responds to: the first word of a sentence or line, when that sentence is at the very
start of a document. The unit is pushed negative there, and the push fades over the first
few dozen tokens of the document:

- a capitalised sentence opener ("The", "In", "What", "These", "It") is strongest;
- a lowercase word right after a sentence or line break is about 40% as strong;
- the copulas "is", "was", "are", "were" are about half as strong as a capitalised opener;
- a capitalised word in mid-sentence is weaker, and other lowercase words weaker still;
- punctuation, digits, spaces, and any token deep in a document give about zero.

Position counts tokens from the start of the current document (the first token is 0 and
predicts 0), so a packed row's document boundaries reset the effect.
"""

from collections.abc import Mapping

READS = ()

PEAK = 0.74        # activation of a capitalised sentence opener at token 1 of a document
DECAY = 20.0       # tokens over which the effect fades, exp(-k / DECAY)
BREAKS = (".", "!", "?", ":", "\n")
COPULAS = ("is", "was", "are", "were")
# weight by kind: capitalised opener, lowercase opener, copula, capitalised mid-sentence, other
WEIGHTS = {"cap_opener": 1.0, "opener": 0.4, "copula": 0.5, "cap": 0.25, "other": 0.15}


def kind_of(prev: str, word: str) -> str:
    """What kind of word this is, given the token before it and the word itself."""
    if prev == "" or prev.strip() == "" or prev.endswith(BREAKS):
        if word[0].isupper():
            return "cap_opener"
        return "opener"
    if word in COPULAS:
        return "copula"
    if word[0].isupper():
        return "cap"
    return "other"


def step(carry, prefix, upstream: Mapping):
    # carry: how many tokens into the current document the previous token was (None at a row start)
    t = prefix.position
    new_doc = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    k = 0 if new_doc else carry + 1
    word = prefix.token_strings[-1].strip()
    if k == 0 or not word[:1].isalpha():
        return k, 0.0
    prev = "" if new_doc else prefix.token_strings[-2]
    weight = WEIGHTS[kind_of(prev, word)]
    return k, -PEAK * weight * 2.718281828 ** (-(k - 1) / DECAY)

programs.sol:
"""A mostly negative spelling feature centered on short 'ow' spellings.

The letters before 'ow' set its strength, and the ending usually
attenuates it. Common families such as know, down, follow and show are
weak exceptions. A few related ew/aw spellings are also recognized.
A small echo carries into the next attached Latin-letter piece, stronger
for word endings such as ing; document boundaries clear that echo.
This is a spelling approximation, not a claim about the words' meanings.
"""
READS = ()


def spelling_response(token):
    stripped = token.strip()
    word = stripped.lower().lstrip('._-/(<[{')
    if 'ow' not in word:
        if word in ('grew', 'blew'):
            return -2.5
        if word in ('crew', 'sew'):
            return -1.5
        if word == 'threw':
            return -1.0
        if word == 'few':
            return -0.3
        if word in ('straw', 'shaw'):
            return -1.2
        return 0.0
    if word.startswith(('know', 'down', 'window', 'allow', 'follow',
                        'browser', 'browse', 'below', 'unknown',
                        'ellow', 'pillow')):
        return -0.03
    if word in ('however', 'tomorrow', 'toward', 'towards', 'rightarrow'):
        return 0.0
    if word.startswith('show'):
        if word.startswith('shower'):
            return -1.0
        return -0.45 if stripped[:1].isupper() else -0.1
    if word.startswith('power'):
        return -1.0 if word in ('powers',) else -0.35
    if word.startswith('own'):
        return -0.9 if word == 'own' and not token.startswith(' ') else -0.05
    if word.startswith(('town', 'brown')):
        return -0.4
    before, after = word.split('ow', 1)
    if not before:
        strength = 5.7
    elif before in ('b', 'p', 't', 'd', 'g'):
        strength = 5.0
    elif before == 'r':
        strength = 3.9
    elif before in ('br', 'cr', 'fl', 'bl', 'gl', 'gr'):
        strength = 3.4
    elif before == 'n':
        strength = 2.25
    elif before == 'l':
        strength = 2.8
    elif before == 'w':
        strength = 3.4
    elif before == 'h':
        strength = 1.55
    elif before in ('sn', 'sl', 'thr', 's'):
        strength = 1.9
    elif before in ('c', 'pr', 'fr', 'arr'):
        strength = 3.1
    else:
        return -0.8 if after == '' else -0.4
    factor = {'': 1.0, 's': 0.8, 'ing': 0.8, 'n': 0.55,
              'd': 0.65, 'er': 0.4, 'ers': 0.4, 'est': 0.35,
              'ed': 0.5, 'der': 0.4, 'ders': 0.6, 'l': 0.45,
              'a': 0.5, 'e': 0.5, 'i': 0.4, 'y': 0.4}.get(after, 0.25)
    if not before and token.startswith(' '):
        factor *= 0.65
    if before in ('gr', 'fl') and after == 'ing':
        factor = 1.0
    if before == 'thr' and after == 's':
        factor = 0.55
    if before in ('t', 'fl') and after in ('er', 'ers'):
        factor = 0.25 if before == 't' else 0.2
    if stripped[:1] in '._-/(<[{':
