    '。': (0.67, 0.76, 0.90, 0.85, 0.79),
    '，': (0.01, 0.28, 0.88, 0.70, 0.36),
    '：': (0.14, 0.46, 0.95, 0.55, 0.43),
    '；': (0.08, 0.24, 0.70, 0.42, 0.40),
    '（': (-0.12, 0.15, 0.78, 0.50, 0.08),
    '）': (0.12, 0.23, 0.64, 0.51, 0.25),
    '！': (0.18, 0.36, 0.67, 0.50, 0.34),
    '？': (0.17, 0.43, 0.67, 0.65, 0.55),
    '、': (-0.08, -0.02, 0.33, 0.19, 0.03),
    '・': (-0.18, -0.11, 0.15, 0.03, -0.11),
    '「': (-0.09, -0.06, 0.14, 0.05, -0.04),
    '」': (-0.03, -0.01, 0.13, 0.20, -0.03),
    '『': (0.05, 0.03, 0.19, 0.10, 0.08),
    '』': (0.08, 0.12, 0.45, 0.26, 0.16),
    '“': (-0.14, -0.08, 0.35, 0.02, 0.02),
    '”': (-0.11, -0.03, 0.03, 0.01, -0.03),
    '‘': (-0.11, -0.06, 0.35, 0.02, 0.04),
    '’': (-0.08, -0.06, -0.05, 0.01, 0.0),
