    '。': (-0.02, 0.13, 0.15, 0.23, 0.08),
    '，': (-0.12, 0.10, 0.14, 0.15, -0.05),
    '：': (-0.11, 0.08, 0.25, 0.35, 0.09),
    '；': (-0.10, 0.05, 0.20, 0.20, 0.05),
    '）': (-0.09, -0.03, 0.03, 0.10, -0.06),
    '？': (-0.07, 0.09, 0.25, 0.20, 0.07),
    '！': (-0.12, 0.04, 0.20, 0.15, 0.0),
