def writing_system(text):
    if any('\u4e00' <= c <= '\u9fff' for c in text):
        return 0
    if any('\u3040' <= c <= '\u30ff' for c in text):
        return 1
    if any(c.isascii() and c.isalpha() for c in text):
        return 2
    if any(c.isdigit() for c in text):
        return 3
    return 4


# Cyrillic letters with familiar Latin-shaped glyphs.
LATIN_LOOKALIKES = frozenset('АВЕКМНОРСТХУаеорсухуІіЈј')


def script(text, low, high):
    return any(low <= c <= high for c in text)


