    elif token == '؟':
        value = 0.17
    elif token == '\x00':
        value = 0.11 if previous.strip().isalpha() else -0.06
    elif token == '<|im_end|>':
        value = (-0.20, -0.12, -0.05, -0.13, -0.06)[column]
        if script(previous, '\u0400', '\u06ff'):
            value = -0.11
    elif token == '<|endoftext|>' and column == 0:
        value = -0.14
    elif mark == '✓':
        value = -0.17 if token.startswith(' ') else -0.07
    elif len(mark) == 1 and script(mark, '\u0400', '\u04ff'):
        if column == 2:
            value = 0.15 if token.startswith(' ') else 0.30
        elif column == 3:
            value = 0.07
        elif mark in LATIN_LOOKALIKES:
            value = 0.07 if mark.isupper() else 0.025
            if token.startswith(' ') and mark.isupper():
                value = -0.02
        else:
            value = -0.02
    elif token == ',':
        value = -0.08 if column == 0 else 0.005
        if previous.strip().isdigit() or previous.strip().isupper():
            value = 0.03
    elif token in ('.', ':') and script(previous, '\u0400', '\u06ff'):
        value = 0.05
    elif token.strip().isdigit() and column == 0:
        value = -0.05
    elif token.isspace() and '\n' in token:
        value = -0.03 if column == 0 else 0.005
    else:
