    "ous", "ant", "ent", "ate", "ed", "ing",
)
ADJECTIVES = {"most", "only", "own", "true", "whole", "entire", "above", "down"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2:
        return None, 0.0
