"""Approximate a source/attribution-marker response.

Strong positive values mark GitHub addresses and author credits. Smaller
values mark workspaces, Java package roots, repository metadata, commercial
domain endings (including email), and credit-giving 'by' phrases. Other
tokens give zero. Gains are training-text estimates. An 80-character tail
joins split names and URLs; state resets for each document.
"""
import re

READS = ()
METADATA = {
    'readme': 0.7, 'license': 0.65, 'copyright': 1.35,
    'repo': 1.2, 'repository': 0.55, 'contributors': 1.1,
}


def response(token, previous, tail):
    word = token.strip()
    name = word.lstrip('./_@"-')
    if word == '.com':
        if tail.lower().endswith('github'):
            if previous.startswith('"'):
                return 10.4
            if previous.startswith('.'):
                return 3.0
            if previous == 'ithub':
                return 6.3
            return 6.5 if previous.startswith(' ') else 7.7
        if 'githubusercontent' in previous:
            return 6.0
        return 1.7 if previous.startswith('@') else 0.35
    if (name.lower() == 'github'
            or word == 'ithub' and tail.endswith('g')):
        if word.startswith('.'):
            return 3.4
        if word.startswith('"'):
            return 1.05
        return 2.1 if token.startswith(' ') else 2.6
    if name.lower() == 'author':
        if previous.strip() == '@' or previous == '__':
            return 6.1
        if word == 'Author' and previous.strip() in {'*', '//', '##', '###'}:
            return 4.3
        if word.startswith('_'):
            return 1.9
        if name == 'Author':
            return 2.5
        return 2.1 if token.startswith(' ') else 3.25
    if name.lower() == 'authors':
        return 1.05 if name.islower() else 1.9
    if word.lower() == 'by':
        if previous == ' Created':
            return 3.35
        if re.search(r'\d\d:\d\d:\d\d$', tail):
            return 4.3
        match = re.search(r'[A-Za-z]+$', tail)
        verb = match[0].lower() if match else ''
        if verb == 'maintained':
            return 1.85
        if verb in {'posted', 'photo', 'reviewed', 'uploaded', 'modified'}:
            return 1.15
        if verb in {'written', 'created', 'developed', 'owned', 'held', 'edited'}:
            return 0.65
        if verb in {'made', 'provided', 'described', 'published', 'illustrated'}:
            return 0.4
        if not previous:
            return 0.72
        return 0.1 if token == ' by' else 0.33
    if name == 'workspace':
        return 1.32 if word.startswith('/') else 0.85
    if word in {'/repos', '/user', '/'} and tail.endswith('github.com'):
        return {'/repos': 6.3, '/user': 4.7, '/': 2.2}[word]
    if word in {'com', 'org'}:
        if 'import' in previous:
            return 1.9
        return 1.2 if previous.strip() == 'package' else 0.45
    if name.lower() == 'git':
        return 1.06 if word.startswith('.') else 0.83
    if word == '@':
        return 0.6 if token.startswith(' ') else 0.27
    if word in {'.md', '_modules'}:
        return 0.6
    return METADATA.get(name.lower(), 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    value = response(token, previous, tail)
    return (doc, token, (tail + token)[-80:]), float(value)

