"""Layer-0 MLP down_proj component 1322: "who made this code, and where is it hosted".

The component writes a signal into the residual stream on words that name a code host, a
source repository, or the author of a file or link. It is hand-written from the token
statistics of about 9,000 training rows; it is not fitted to the component's weights.

Strongest: the '.com' of 'github.com' (about 7.5), and the '/repos' of
'api.github.com/repos' (about 6). Next: '.github', 'github' / 'ithub', 'author' /
'Author' / 'AUTHORS' / '@author' (about 2.5 to 3.5), and 'by' after an authorship verb
('Created by' in file headers, 'written by', 'maintained by'). Weaker (about 0.5 to 1.5):
repository-file words ('.git', 'git', 'commit', 'repo', 'README', 'LICENSE', '.md',
'workspace', '.gitignore'), account words ('Users', 'user', 'contacts'), Java
'import org.' / 'import com.', an email or social domain ('@gmail.com', 'twitter.com'),
and '@' in doc-comments. Everything else predicts zero.
"""

READS = ()

# Tokens that name GitHub, and their typical activation.
HOST = {".github": 3.4, "github": 2.5, "ithub": 2.8, "/github": 4.5, "githubusercontent": 6.0}

# Words for an author, and their typical activation.
AUTHOR = {"author": 3.0, "authors": 1.2, "作者": 1.2}

# Verbs after which 'by' names the person who made something.
AUTHORSHIP_VERBS = {
    "created": 0.7, "maintained": 2.0, "written": 0.6, "posted": 1.0, "developed": 0.65,
    "owned": 0.7, "edited": 0.7, "submitted": 0.6,
}

# Words of a repository and its files.
REPO = {
    "/workspace": 1.3, "workspace": 0.9, ".git": 1.1, "git": 0.9, "commit": 0.8, "repo": 1.0,
    "/repository": 0.7, "/repos": 0.5, "readme": 0.9, "license": 0.6, "copyright": 1.3,
    ".md": 0.6, "/vendor": 0.6, "_modules": 0.6,
}

# Account and contact words.
ACCOUNT = {
    "users": 1.0, "user": 0.4, "/user": 1.8, "contacts": 0.7, "email": 0.4, "/org": 0.8,
    ".org": 0.3,
}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    doc = prefix.document_ids[-1]
    # The up-to-three tokens before this one, if they are in the same document.
    before = [
        (s.strip(), _word(s))
        for s, d in zip(prefix.token_strings[-4:-1], prefix.document_ids[-4:-1])
        if d == doc
    ]
    prev = [w for _, w in before]
    near = "".join(prev)
    last_raw = before[-1][0] if before else ""
    value = 0.0
    if word in (".com", "com") and "github" in near:
        value = 7.5
    elif word == "/" and near.endswith("github.com"):
        value = 2.5
    elif word == "/repos" and "github" in near:
        value = 6.3
    elif word == "by" and prev and last_raw == "Created":
        value = 3.2
    elif word == "by" and prev and prev[-1] in AUTHORSHIP_VERBS:
        value = AUTHORSHIP_VERBS[prev[-1]]
    elif word in ("org", "com") and prev and prev[-1] == "import":
        value = 1.5 if word == "org" else 0.8
    elif word in (".com", "com") and near.endswith(("gmail", "twitter", "example")):
        value = 1.8
    elif word == "ignore" and prev and prev[-1] == ".git":
        value = 0.7
    elif word in HOST:
        value = HOST[word]
    elif word in AUTHOR:
        value = AUTHOR[word]
    elif word in REPO:
        value = REPO[word]
    elif word in ACCOUNT:
        value = ACCOUNT[word]
    elif word == "@":
        value = 0.6
    return carry, float(value)

