    value = 0.0

    # GitHub names and domains are the strongest lexical cues.
    if "github" in token:
        value = max(value, 2.4)
    if ".com" in token:
        github_context = "github" in token or past.endswith("github")
        value = max(value, 4.8 if github_context else 1.0)
    if any(token.endswith(suffix) for suffix in REPO_EXTENSIONS):
        value = max(value, 1.0)

    # Mark author labels and a few common forms of attribution.
    if label in ("author", "authors", "authorship"):
        value = max(value, 2.0)
    elif label in ("contributor", "contributors"):
        value = max(value, 0.9)
    if label == "by":
        value = max(value, 0.16)
        if past.endswith(CREDIT_VERBS):
            value = max(value, 0.5)

    # Project paths, repository file names, and source package declarations.
    if "workspace" in token:
        value = max(value, 1.0)
    if token.endswith("_modules"):
        value = max(value, 0.55)
    if any(marker in token for marker in PROJECT_MARKERS):
        value = max(value, 0.5)
    if label in ("com", "org", "java", "example") and past.endswith(
        ("import", "package")
    ):
        value = max(value, 1.5)
    if token == "@":
        value = max(value, 0.6)
    if "/" in token:
        value = max(value, 0.08)

    next_history = (history + (raw,))[-12:]
    return (document, next_history), float(value)

"""Use small negative guesses for boundary-like special tokens."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, -0.75
    if token == "</think>":
        return None, -0.65
    return None, 0.0

"""Estimate the small negative signal on words that mark means or route.

The clearest cues are English 'by', 'via' and 'through', plus Chinese
counterparts such as '凭', '用' and '通过'. '通过' has a much larger
response than the ordinary links. The rule recognizes words, not their
sentence-specific use, so it misses context-dependent cases.
"""
READS = ()

ENGLISH_LINKS = {"by": -0.4, "via": -0.9, "through": -0.75}
METHOD_WORDS = frozenset({
    "通过", "憑", "凭", "用", "以", "由于", "因為", "因为", "受",
    "據", "据", "从", "從", "采用", "結合", "结合", "使用",
    "über", "durch", "thông", "qua",
})


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip()
    word = raw.lower()
    if word == "通过":
        return None, -5.8
    if word in ENGLISH_LINKS:
        return None, ENGLISH_LINKS[word]
    if word in METHOD_WORDS:
        return None, -0.7
    # A capitalized By suffix is common in code names like getByDay.
    if raw.endswith("By"):
        return None, -1.1
    return None, 0.0

programs.sol:
"""Number boundaries: the first non-digit token after a numeral.

Letters, clock suffixes, month names, units, and opening punctuation respond
positively. Decimal punctuation stays quiet; percentages and ordinal suffixes
are often negative. Written-out numbers and space-separated boundaries are weaker.
Nonbreaking spaces after digits also respond strongly. Most other contexts
return zero. Positive responses are larger early in a document and smaller
for digits embedded in names or identifiers. State resets at document changes.
"""
READS = ()
NUMBER_WORDS = set('''zero one two three four five six seven eight nine ten
    eleven twelve thirteen fourteen fifteen sixteen seventeen eighteen nineteen
    twenty thirty forty fifty sixty seventy eighty ninety hundred thousand
    million billion trillion'''.split())
MONTHS = set('''Jan Feb Mar Apr May Jun Jul Aug Sep Sept Oct Nov Dec January
    February March April June July August September October November December'''.split())
CALENDAR = set('day days week weeks month months year years'.split())
FUNCTIONS = set('''the of for from by on is are was were be been this which
    who it its their his her my our your can has have'''.split())


def number_boundary(s):
    w, spaced = s.strip(), s.startswith(' ')
    if not w:
        if '\xa0' in s:
            return 0.83
        if '\n' in s or '\r' in s:
            return 0.04 if spaced else -0.06
        return 0.18 if s.startswith('  ') else 0.0
    if w.isdigit():
        return -0.008
    if w in {'am', 'pm', 'AM', 'PM'}:
        return 1.15 if spaced else 1.3
    if w in MONTHS or w in {'BC', 'AD', 'BCE', 'CE'}:
        return 0.8
    if w in CALENDAR:
        return -0.06
    if w in {'h', 'hr', 'hrs', 'min', 'mins'}:
        return 0.9
    if w in {'mm', 'cm', 'mg', 'mcg', 'ml', 'px'}:
        return 0.13
    if w in {'th', 'nd', 'rd', 'percent', 'times', 'mod'}:
        return -0.22
    if w.lower() in NUMBER_WORDS or w == 'st':
        return 0.07
    if w.isalpha():
        if not w.isascii():
            if w in {'年', '日', '년'}:
                return 0.02
            if len(w) == 1 and w in '万萬千亿億':
                return 1.0
            return 0.5 if len(w) == 1 else 0.25
        if len(w) == 1:
            if w.isupper():
                # K often marks a thousand/kilo-scale quantity.
                return 1.27 if w == 'K' and not spaced else 0.9
            if w == 'x':  # multiplication rather than a letter label
                return 0.18
            return 0.30 if w in {'s', 'd'} and not spaced else 0.57
        if w.isupper():
            return 0.46
        if w.lower() in {'and', 'but', 'with', 'as'}:
            return 0.01
        if w.lower() in FUNCTIONS:
            return 0.12
        if w.lower() in {'in', 'at'}:
            return 0.36
        return 0.25 if spaced else 0.15
    c = w[0]
    if c in '([{':
        return 0.56 if spaced or len(w) == 1 else 0.30
    if c in ',.':
        return (0.5 if c == '.' else 0.34) if spaced else 0.0
    if c in '/%;':
        return 0.18 if spaced else -0.18
    if c in '-–—:':
        return 0.15 if spaced else 0.0
    if c in '\"\'`”’':
        return 0.43 if spaced or len(w) == 1 else 0.08
    if c == '\\':
        return 0.47 if len(w) == 1 else 0.0
    if c in '€£¥₹':
        return 0.85
    if c in '±√°':
        return 0.6 if c == '±' else 0.3
    if c == '|':
        return 0.4 if spaced and len(w) == 1 else 0.04
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before, position, embedded = '', '', 0, False
    else:
        _, previous, before, position, embedded = carry
        position += 1
    w = s.strip()
    if previous.strip().isdigit():
        value = number_boundary(s)
        if value > 0.2:
            value *= 1.25 if position < 10 else 1.1 if position < 50 else (
                1.0 if position < 100 else 0.9)
            if embedded:
                value *= 0.85
    elif previous.strip().lower() in NUMBER_WORDS:
        value = -0.2 if w.lower() in CALENDAR | NUMBER_WORDS else (
            0.08 if w.isalpha() or w.startswith('(') else 0.0)
    elif previous.isspace() and before.strip().isdigit():
        value = 0.07 if w.isalpha() else 0.0
    else:
        value = 0.0
    if w.isdigit() and not previous.strip().isdigit():
        embedded = bool(previous) and previous[-1].isalpha()
    return (doc, s, previous, position, embedded), float(value)

programs.luna:
"""Use a nearby number as a cue for a positive component activation.

In sampled high-response examples, a number often comes just before a unit,
label, date, or other nonnumeric token. This small rule captures that local
pattern but does not try to identify which kind of phrase follows.
"""
READS = ()


def _is_decimal_token(text):
    text = text.strip()
    return bool(text) and all(char.isdecimal() for char in text)


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    documents = prefix.document_ids
    current = strings[-1]
    follows_number = False

    if current.strip() and not _is_decimal_token(current):
        for distance in (1, 2, 3):
            index = len(strings) - 1 - distance
            if index < 0 or documents[index] != documents[-1]:
                break
            previous = strings[index]
            if _is_decimal_token(previous):
                follows_number = True
                break
            if previous.strip():
                break

    return None, 0.10 if follows_number else 0.0

programs.sol:
"""Approximate a signal for unfinished Unicode characters at token boundaries.

A trailing replacement character in both the token and decoded prefix is the
cue.  Fragments which finish a character, or add no decoded text, get zero.
Whitespace and the last 40 decoded characters' script set the usual strength.
A Japanese long-vowel mark, hiragana shi, or single Cyrillic letter bundled
with an unfinished next character gets a larger response.  Some completed
Japanese glyphs, Greek omicron, and turn/thinking end markers have weaker
responses.  All other tokens get zero; script context resets per document.
"""
READS = ()
REPLACEMENT = '\ufffd'


def recent_script(text):
    for name, low, high in (
        ('Japanese', '\u3040', '\u30ff'),
        ('Korean', '\uac00', '\ud7a3'),
        ('Han', '\u4e00', '\u9fff'),
        ('Indic', '\u0900', '\u0dff'),
    ):
        if any(low <= c <= high for c in text):
            return name
    return 'Other'


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    new_document = carry is None or carry[0] != document
    if new_document:
        start = (0 if prefix.position == 0 else
                 len(prefix.text_prefixes[-2]))
        carry = (document, start)
    token = prefix.token_strings[-1]
    if not token.endswith(REPLACEMENT):
        if token in ('ー', 'ッ'):
            value = 0.74  # Japanese vowel/consonant length marks
        elif token == 'し':
            value = 0.94  # hiragana shi
        elif token in ('ο', 'ό'):
            value = 0.71  # Greek omicron, optionally stressed
        elif token == '<|im_end|>':
            value = 0.26
        elif token == '</think>':
            value = -0.30
        else:
            value = 0.0
        return carry, value

    text = prefix.text_prefixes[-1]
    if not text.endswith(REPLACEMENT):
        return carry, 0.0
    if not new_document and text == prefix.text_prefixes[-2]:
        return carry, 0.0
    context = text[max(carry[1], len(text) - 41):-1]
    script = recent_script(context)
    before = token.rstrip(REPLACEMENT)
    if not before:
        if len(token) > 1:
            value = 4.4  # end of one split character plus start of another
        else:
            value = {'Japanese': 1.55, 'Korean': 1.8, 'Han': 1.78,
                     'Indic': 2.10, 'Other': 1.26}[script]
    elif before.isspace():
        value = {'Japanese': 0.65, 'Korean': 1.15, 'Han': 0.11,
                 'Indic': 0.90, 'Other': 0.90}[script]
    elif before == 'ー':
        value = 6.34
    elif before == 'し':
        value = 4.47
    elif len(before) == 1 and '\u0400' <= before <= '\u04ff':
        value = 3.7  # one Cyrillic letter followed by an unfinished one
    else:
        value = 1.8
    return carry, value

programs.haiku:
"""A standalone space token (' ', the space Qwen puts before a number or word, e.g. the
space in 'year 2012' or 'Tlf.: 2082 5939') gets a value set by the token before it plus how
many standalone spaces came recently in the same document. Predicts 0 for all other tokens,
except that a space opening a document gets a large fixed value (2.08).
"""

READS = ()

DOC_START_VALUE = 2.08    # a space that is the first token of a document
DECAY = 0.9               # each earlier token's weight is multiplied by this per step
SPACE_GAIN = 0.33         # per unit of decayed count of earlier standalone spaces


def prev_class_value(prev):
    core = prev.strip()
    if core.isdigit():
        return -0.76      # after a digit
    if prev[:1] != " " and core.isascii() and core.isalpha():
        return -0.47      # right after a bare word
    if core in (",", ";"):
        return 0.16       # after a comma or semicolon
    return -0.15          # anything else (roughly neutral)


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    recent = 0.0 if new_doc else carry          # earlier spaces, decayed, same document
    is_space = tok == " "
    if is_space and new_doc:
        value = DOC_START_VALUE
    elif is_space:
        value = prev_class_value(prefix.token_strings[-2]) + SPACE_GAIN * recent
    else:
        value = 0.0
    return recent * DECAY + (1.0 if is_space else 0.0), value

programs.luna:
"""A small cue for spaces just after number digits or separators."""
READS = ()

def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != " ":
        return None, 0.0
    pos = prefix.position
    if pos == 0 or prefix.document_ids[pos - 1] != prefix.document_ids[pos]:
        return None, 0.0
    previous = prefix.token_strings[pos - 1].rstrip()
    if previous.endswith(","):
        return None, 0.18
    if previous and previous[-1].isdigit():
        return None, -0.15
    return None, 0.0

programs.sol:
"""A mostly lexical response to pages, with weaker flat-surface vocabulary.

The largest values belong to page words (including code names and translations).
Sheets, surfaces, sides, and rooms produce smaller values. Day/night and price
words are separate weaker responses, not evidence of a page-related topic.
The preceding token and response handle 'side of', 'page of', and
Russian page-word endings. Remembered context resets at document boundaries.
"""
READS = ()

# Familiar word classes, with response strengths estimated from training text.
SURFACES = (
    (2.0, {'sheet', 'sheets'}),
    (1.3, {'sides', 'slide', 'slides'}),
    (1.1, {'surfaces', 'screens', 'margins', '屏', '屏幕'}),
    (1.0, {'side', 'screen', 'creen'}),
    (0.8, {'surface', 'plate', 'plates', 'shelf', 'shelves', 'roofing', 'trays',
           'bedroom', 'bathroom', '板', '层', '屋顶', '界面', '表面'}),
    (0.7, {'floor', 'floors', '侧', '側', '版'}),
    (0.6, {'room', 'rooms', 'row', 'rows', 'roof', 'roofs', 'layers',
           'classroom', 'ceiling'}),
    (0.5, {'layer', 'wall', 'walls', 'plane', 'planes', 'margin', '面'}),
    (0.4, {'panel', 'panels', 'scene', 'scenes', '片'}),
)
DOCUMENTS = (
    (0.8, {'worksheet', 'worksheets', 'browser'}),
    (0.7, {'document', 'html', '纸'}),
    (0.6, {'pdf', 'manuscript', '网站', '文档', 'spreadsheet'}),
    (0.4, {'paper', 'papers', 'doc', 'docs', 'documents', 'website'}),
)
TIME_AND_PRICE = (
    (1.3, {'price', '价格', '價格'}),
    (1.1, {'prices', 'priced', 'pricing', '价', '價'}),
    (1.0, {'afternoon'}),
    (0.7, {'night', 'nights', 'цена', 'prix'}),
    (0.5, {'days', 'morning'}),
)
RESPONSES = {w: v for v, words in SURFACES + DOCUMENTS + TIME_AND_PRICE
             for w in words}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = '', 0.0
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
    token = prefix.token_strings[-1].strip()
    word = token.lstrip('._-/(&').lower()
    value = RESPONSES.get(word, 0.0)

    if word in {'page', 'pages'}:
        value = 5.6 if word == 'page' else 5.1
        if token in {'Page', 'Pages'}:
            value += 0.8 if word == 'page' else 0.45
        if token.isupper():
            value = 4.3
        elif token.startswith(('_', '/', '(', '&')):
            value -= 0.8
        elif token == '.Page':
            value = 4.5
        if previous in {'web', 'home', 'landing'}:
            value -= 1.3
    elif word in {'страниц', 'страница', 'страницы', '页面', '页', 'ページ'}:
        value = 5.7
    elif word in {'página', 'páginas', '페이지', '一页'}:
        value = 4.7
    elif word in {'webpage', 'webpages', '网页', '網頁'}:
        value = 4.4
    elif word in {'pagina', 'pagine', 'ágina', 'ginas'}:
        value = 3.5
    elif word in {'seite', 'seiten', 'pagesize', 'pagecount', 'pagenumber'}:
        value = 2.6
    elif word in {'homepage', '首页', '主页'}:
        value = 1.7
    elif word == 'pag':
        value = 1.4
    elif token.endswith('Page'):
        value = 3.8
    elif word == 'day':
        value = 1.05 if token == 'Day' else 0.77
    elif word == 'of':
        value = -0.02
        if previous in {'page', 'pages'}:
            value = 1.8
        elif previous in {'sheet', 'sheets'}:
            value = 1.1
        elif previous in {'side', 'sides'}:
            value = 0.88
        elif previous in {'price', 'prices', 'margin', 'margins'}:
            value = 0.6
        elif previous != 'of' and strength > 0.4:
            value = 0.6 * min(strength, 1.0)
    elif previous == 'страниц' and word in {'а', 'ы', 'е', 'у', 'ей', 'ах'}:
        value = 3.0

    return (doc, word, value), float(value)

"""A detector for typographic spacing and within-line alignment.

Isolated non-breaking spaces dominate. Ordinary spaces and newlines are quiet;
space runs respond inside a line, not immediately after a newline. Tabs have
separate indentation and column-separator responses. Smaller side responses
cover typographic notation, zero-width marks, and Arabic vocalization marks.
Only the preceding token is retained, resetting at document boundaries.
"""
READS = ()

# Token 378 is the unfinished UTF-8 prefix E2 80, shared by characters
# U+2000--U+203F (including en/em/thin and narrow non-breaking spaces).
UNICODE_SPACING_PREFIX = 378
NBSP = "\u00a0"
ZERO_WIDTH_SPACE = "\u200b"
ZERO_WIDTH_NON_JOINER = "\u200c"
NON_BREAKING_HYPHEN = "\u2011"
ARABIC_MARKS = {
    '\u064b': 0.54,  # fathatan
    '\u064e': 1.0,   # fatha
    '\u064f': 1.15,  # damma
    '\u0650': 0.52,  # kasra
    '\u0651': 1.6,   # shadda
    '\u0652': 0.17,  # sukun
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    prev = '' if carry is None or carry[0] != doc else carry[1]
    after_newline = '\n' in prev or '\r' in prev
    value = 0.0
    if s == NBSP:
        if not prev:
            value = 5.8
        elif after_newline:
            value = 3.8
        elif prev.isspace():
            value = 3.4 if prev == NBSP else 2.6
        elif prev.endswith('–'):
            value = 1.9 if prev.startswith(' ') else 3.3
        elif prev[-1:].isdigit():
            value = 4.5
        else:
            value = 4.6 if prev.startswith(' ') else 5.0
    elif s == NBSP * 2:
        value = 0.5 if prev.isspace() else 1.5
    elif s and not s.strip(NBSP):
        value = 0.85 if len(s) == 3 else 0.15
    elif s == ' ' + NBSP:
        value = 0.05 if prev.isspace() or not prev else 0.95
    elif s and not s.strip(' \t'):
        indentation = after_newline
        tabs = s.count('\t')
        if s == '\t':
            value = 0.47 if indentation else 0.60 if prev.isspace() else 1.47
        elif tabs == 1:
            value = 0.84 if len(s) <= 20 else 0.65
            if indentation:
                value = 0.0
            elif not prev:
                value *= 0.7
        elif tabs > 1:
            value = -0.08 if indentation else 0.85
        elif len(s) >= 2:
            value = -0.02 if indentation else 0.55 if not prev else 0.78
            if len(s) > 24:
                value *= 0.6
            if len(s) > 64:
                value *= 0.3
    elif s in ('nbsp', '&nbsp'):
        value = 3.1 if s == 'nbsp' else 5.2
    elif s in ('~', 'mathrm', NON_BREAKING_HYPHEN):
        value = 0.85
    elif s.strip(' ') in (ZERO_WIDTH_SPACE, ZERO_WIDTH_SPACE * 2):
        value = 1.5 if s == ZERO_WIDTH_SPACE else 1.2
    elif s == ZERO_WIDTH_NON_JOINER:
        value = 0.78
    elif s in ARABIC_MARKS:
        value = ARABIC_MARKS[s]
    elif int(prefix.token_ids[-1]) == UNICODE_SPACING_PREFIX:
        value = 1.8 if prev.isspace() else 3.0
    elif '\ufffd' in s:
        # A continuation byte can finish a spacing character even though
        # decoding this token alone displays only the replacement character.
        last = prefix.text_prefixes[-1][-1:]
        if last and '\u2000' <= last <= '\u200a':
            value = 3.5
        elif last == '\u202f':
            value = 3.8
    return (doc, s), value

programs.luna:
"""Recognize indentation and aligned text: tabs, runs of spaces, and NBSP."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if not token or not token.isspace():
        return None, 0.0
    if '\u00a0' in token:
        return None, 3.5
    if '\n' in token or '\r' in token:
        return None, 0.0
    if '\t' in token or len(token) > 1:
        return None, 0.65
    return None, 0.0

programs.sol:
"""Approximate the component's negative pulses on list-label punctuation.

Periods and closing parentheses following numeric, lettered, or Roman-letter
labels respond most strongly near a line break. A fitted pulse fades with
line position; whitespace counts lightly so indentation does not hide labels.
Its size depends on the label's shape, parentheses, and preceding line ending.
Short inline labels after colons can also start lists. Bullet dashes, circled
numbers, and lettered choice blanks have separate small rules.

State resets at document boundaries. Other token types predict zero, leaving
incidental lexical activations unmodeled. The constants are empirical fits,
not a reconstruction of the model's internal attention or MLP.
"""
import math
import re

READS = ()
LABEL = re.compile(r'(\d+|[A-Za-z]+|[一二三四五六七八九十百]+)$')
ROMAN = re.compile(r'[ivxlcdmIVXLCDM]+$')


def marker(line, ending, previous, distance, closer):
    match = LABEL.search(line)
    label = match[0] if match else ''
    head = line[:match.start()] if match else line
    parenthesis = head.endswith(('(', '（'))
    if parenthesis:
        head = head[:-1]
    pulse = math.exp(-max(0, distance - 1) / 2.0)
    if not ending:
        pulse *= 0.3
    number = label.isdecimal()
    letter = len(label) == 1 and label.isascii() and label.isalpha()
    roman = bool(label) and bool(ROMAN.fullmatch(label))
    # Colons and semicolons can introduce an inline enumeration.
    inline_label = bool(re.search(r'[:：;；]\s+$', head))
    outside_brackets = head.rfind('(') <= head.rfind(')')
    if inline_label and outside_brackets and len(label) <= 2:
        pulse = max(pulse, 0.7)
    if number:
        body, amplitude = -0.02, -2.28 if closer else -1.68
        digit = int(label[-1])
        if digit == 1:
            amplitude -= 0.91 if closer else 0.42
        elif digit == 0:
            amplitude += 0.59 if closer else 0.82
        else:
            amplitude += (0.26 if closer else 0.56) * (digit - 2) / 7
        if parenthesis and not closer:
            return 0.1
        if parenthesis and closer and len(label) == 1:
            body -= 0.4
            amplitude += 0.4
        elif parenthesis and closer:
            body += 0.25
    elif letter and label.lower() in 'abcde':
        body, amplitude = (-0.41, -2.97) if closer else (-0.49, -2.62)
        if closer and not parenthesis:
            amplitude -= 0.3
            if not ending and distance <= 2:
                pulse = 1.0
        if label.lower() == 'a':
            amplitude -= 0.22 if closer else 0.42
        elif label.lower() == 'e':
            amplitude += 0.14 if closer else 0.51
    # Common coordinate variables in function calls are not list labels.
    elif letter and label.lower() in 'xyz' and parenthesis and head[-1:].isalnum():
        return 0.0
    elif roman:
        body, amplitude = (-0.24, -2.0) if closer else (-0.21, -1.34)
    elif letter:
        body, amplitude = (0.0, -1.50) if closer else (0.0, -1.22)
    elif label and all(c in '一二三四五六七八九十百' for c in label):
        body, amplitude = -0.1, -2.1
    elif label:
        body, amplitude = 0.0, -0.1 if closer else -0.25
    else:
        body, amplitude = 0.0, -0.95 if closer else -0.71
    if parenthesis and (number or letter or roman):
        body += -0.23 if closer else 0.19
        amplitude += 0.24 if closer else 0.16
        if previous == label and (letter or roman):
            body -= 0.97 if closer else 0.18
    amplitude -= (0.21 if closer else 0.64) * (':' in ending)
    amplitude -= (0.57 if closer else 0.26) * ('.' in ending)
    amplitude -= (0.0 if closer else 1.08) * ('：' in ending)
    amplitude -= (0.22 if closer else 0.71) * ('。' in ending)
    amplitude -= (0.54 if closer else 0.26) * ('?' in ending or '？' in ending)
    return body + pulse * amplitude


def predict_token(carry, token, document):
    if carry is None or carry[0] != document:
        carry = (document, '', '', '', 0)
    _, line, ending, previous, distance = carry
    value = 0.0
    if token in {'.', '．', '、', ')', '）', ').', '.)'}:
        closer = token in {')', '）', ').', '.)'}
        value = marker(line, ending, previous, distance, closer)
        if token in {').', '.)'}:
            value = 0.6 * value - 0.15
        if token == '、':
            value *= 0.8
    elif token in {'-', ' -'} and not line.strip():
        value = -0.4 - 0.25 * ('.' in ending or '。' in ending)
        value -= 0.4 * (':' in ending or '：' in ending)
        value += 0.15 * ('\n\n' in ending) - 0.3 * token.startswith(' ')
    elif token == ' )' and re.fullmatch(r'\s*[a-eA-E0-9]\s*\(', line):
        value = -2.4 if line.strip()[:1].isdigit() else -3.2
    elif len(token) == 1 and '①' <= token <= '⑳':
        value = -3.2
    if '\n' in token:
        last_character = (line + token).split('\n', 1)[0].rstrip()[-1:]
        ending = last_character + '\n' * token.count('\n')
        line = token.rsplit('\n', 1)[-1]
        distance = int(bool(line.strip()))
    else:
        line = (line + token)[-160:]
        distance += 0.25 if token.isspace() else 1
    return (document, line, ending, token, distance), float(value)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if '�' in token:
        character = prefix.text_prefixes[-1][-1:]
        if character and '①' <= character <= '⑳':
            token = character
    return predict_token(carry, token, prefix.document_ids[-1])

"""A class-word detector, with weaker spelling and meaning neighbours.

The literal 'class' is strongest. Case and token boundaries change its
strength; plurals, derivatives, identifiers, and a few translations are
weaker. 'Glass' and 'lass' also respond. Local context distinguishes code
modifiers, HTML attributes, Python __class__, and phrases like 'class of'.
Everything else is predicted as zero; this omits small unrelated responses.
"""
READS = ()
ACCESS = {'public', 'private', 'protected'}
MODIFIERS = {'internal', 'static', 'sealed', 'final', 'export', 'default'}


def lexical(token):
    word = token.strip().lstrip('_.-/:<(\"\'[@$,')
    low = word.lower()
    if low == 'class':
        if word == 'Class':
            if token.startswith(' '):
                return 6.3
            return 5.9 if token[0] in '_.-(\t' else 6.8
        if word == 'CLASS':
            return 5.3 if token.startswith(' ') else 6.4
        if token.startswith(' '):
            return 4.95
        if token.startswith(('.', '-')):
            return 5.6
        if token.startswith(('<', '[')):
            return 3.5
        if token.startswith('('):
            return 4.3
        return 5.9 if token.startswith('\t') else 6.5
    if low == 'classes':
        return 4.5
    if low == 'classical':
        return 3.2
    if low in {'classic', 'classics'}:
        return 1.85
    if low.startswith('classif'):
        return 1.9 if low == 'classified' else 1.5
    if low.startswith('classroom'):
        return 2.0
    if low.startswith('classmate'):
        return 1.0
    if low.startswith(('subclass', 'superclass')):
        return 2.4
    if 'class' in low:
        return 4.4 if low.endswith('class') else 3.1
    if low in {'lass', 'lasses'}:
        return 3.3 if low == 'lass' else 2.6
    if low == 'glass':
        return 2.2
    if low == 'glasses':
        return 1.45
    # Class/classroom translations and common code abbreviations.
    if low in {'classe', 'clase', 'класс'}:
        return 3.0 if low != 'класс' or not token.startswith(' ') else 4.3
    if low in {'クラス', 'klass'}:
        return 3.7
    if low in {'类', '類', '阶级', '班级', '班'}:
        return 1.7
    if low in {'经典', '古典', '玻璃'}:  # classic, classical, glass
        return 2.0
    if low in {'课', '課', '教室'}:  # lesson, classroom
        return 0.95
    if low in {'clazz', 'cls'}:
        return 2.0
    if low in {'struct', 'enum'}:
        return 0.8 if low == 'struct' else 0.45
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = int(prefix.document_ids[-1])
    reset = carry is None or carry[0] != doc
    prev = '' if reset else carry[1]
    word, previous = token.strip().lower(), prev.strip().lower()
    value = lexical(token)
    if word == 'class' and token.startswith(' '):
        if previous in ACCESS:
            value -= 2.05
        elif previous in MODIFIERS:
            value -= 1.4
        elif previous in {'abstract', 'partial'}:
            value -= 2.5
        elif previous in {'span', 'div', 'code'}:
            value += 0.45
    if token == 'class':
        if reset:
            value = 8.65
        elif prev.endswith('__'):
            value += 1.3
    if word == 'glass' and previous == 'stained':
        value += 0.85
    if token == ' of':
        value = {'class': 2.0, 'classes': 1.4,
                 'classification': 0.95, 'glass': 0.85}.get(previous, value)
    if previous == 'class':
        if token in {'="', "='"}:
            value = 0.88
        elif token == ' ':
            value = 0.4
        elif word in {'ical', 'ically', 'ified', 'ifying', 'ifications'}:
            value = 2.3 if word == 'ical' else 1.3
    return (doc, token), value

"""Spelling-dependent document-onset response, with a short opening-word tail.

High-importance training examples concentrate at document starts. Unspaced
lowercase pieces lean negative, particularly vowel-led pieces and suffixes.
Single ASCII capitals, most digits, hash headings and code words lean positive;
leading whitespace changes these biases. The constants summarize training
averages and slopes, not token IDs. A three-token correction follows an
unspaced opening word; later context-dependent fluctuations are omitted.
"""
import unicodedata

READS = ()
INFLECTIONS = set('s es ed ing er est'.split())
DERIVATIONS = set('''tion ation ition sion ion ions tions ations sions
ment ments ness less ful ous ious eous able ible ables ibles ability
ibility ity ities ty al ial ical ic ics ically ally ly ily arily ory
ary ery ist ists ism isms ive ives ize ise ized ised izing ising en
ence ance ency ancy ant ent ants ents dom hood ship ward wards wise'''.split())
CODE_WORDS = set('''import from package using namespace class public
private protected static const def return function var let if else for
while switch case try except include export module require use print
console async await'''.split())
GRAMMAR_WORDS = set('''a an of to in on for with by at as and or but
is are was were be have has it this that i you he she we they not no
all some'''.split())
QUESTIONS = set('What How Why When Where Who Which'.split())


def onset_value(s):
    t = s.strip()
    n = len(t)
    if s.startswith('<|'):
        return 0.035
    if '\ufffd' in s:
        return -0.49 if s.startswith(' ') else -1.07
    if not t:
        return -0.13 if '\n' in s else 0.04 if '\t' in s else 0.25
    if t.isdecimal():
        return -0.016 if t == '0' else 0.22
    if s[0].isspace():
        if t == 'the':
            return 0.41
        if t in GRAMMAR_WORDS:
            return 0.07
        if t.islower():
            return -0.076
        if t.isalpha():
            return -0.135
        return 0.23 if t[0] in '([' else 0.02
    if t[0] == '#':
        if set(t) == {'#'}:
            return 1.05
        return 0.31 if t.startswith('#!') else 0.58
    if t.startswith(('//', '/*', '<?')):
        return 0.42
    if t[0] in '([':
        return 0.18
    if t[0] in ')]':
        return -0.55 if n == 1 else -0.19
    if t[0] in ',;':
        return -0.18
    if not any(c.isalpha() for c in t):
        return -0.04
    if t in CODE_WORDS:
        return 0.39
    if t.isascii() and t.isalpha():
        if t.isupper():
            return 0.21 if n == 1 else -0.34
        if t.istitle():
            if t == 'The':
                return 0.85
            return 0.41 if t in QUESTIONS else -0.03
        if t.islower():
            vowels = sum(c in 'aeiouy' for c in t)
            if t in INFLECTIONS:
                return 0.89 - 1.18*n
            if t in DERIVATIONS:
                return 0.33 - 0.83*n + 0.57*max(n-4, 0)
            if n == 1:
                return -0.25
            if t[0] in 'aeiouy':
                return min(-0.10, -0.28*n - 0.43*vowels
                           + 0.70*max(n-4, 0))
            return -0.75 if n <= 6 else -0.40
    if any('\u3400' <= c <= '\u9fff' or '\u3040' <= c <= '\u30ff'
           for c in t):
        return -0.18 if n == 1 else -0.04
    if t.islower():
        plain = unicodedata.normalize('NFD', t)
        if any('\u0400' <= c <= '\u052f' for c in t):
            return -1.38
        return -1.6 if plain[0] in 'aeiouy' else -0.35
    return -0.17


def word_piece(s):
    return (bool(s) and not s[0].isspace()
            and any(c.isalpha() or c == '\ufffd' for c in s)
            and not s.startswith('<|'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        value = onset_value(s)
        negative = min(value, 0.0) if word_piece(s) else None
        return (doc, 0, negative), float(value)

    _, age, first_negative = carry
    age += 1
    if first_negative is None or age > 3 or not word_piece(s):
        return (doc, 4, None), 0.0

    # A fading memory of the first piece, plus the current piece's spelling.
    first_weight = (0.0, 0.62, 0.39, 0.19)[age]
    offset = (0.0, 0.096, 0.044, 0.015)[age]
    current_negative = min(onset_value(s), 0.0)
    value = offset + 0.14*current_negative + first_weight*first_negative
    return (doc, age, first_negative), float(value)

"""A partial lexical explanation of this layer-zero component.

Listed trust, approval, and criticism words receive negative class averages;
listed distress and emotional-experience words receive positive averages.
Separate rules cover several formatting patterns, technical spellings, and
the split UTF-8 encoding of head/page-radical CJK characters. A previous-word
state recognizes a few social-evaluation complements and trust plurals.
A small negative bias marks the first two document positions, strongest on
a document-initial message-start marker. Other tokens predict zero. These
rules omit most weak token-specific responses and full contextual variation.
"""
READS = ()

TRUST = {"trust"}
TRUST_FORMS = set("trusts trusted trusting trustworthy".split())
RELIANCE = set('trustee dependable reputable '
              'dependence dependency confidence doubt doubts skepticism '
              'scepticism suspicious questionable dubious legitimacy betrayal '
              'deceit'.split())
PRAISE = set('praise praises'.split())
APPROVAL = set('approval endorsement appreciation gratitude satisfaction '
              'devotion respect respects supportive supporter supporters '
              'backing forgiven'.split())
CRITICISM = set('blame criticism criticisms contempt scrutiny dismiss '
               'annoying frustration frustrating disappointment disappointing '
               'disgust disgusted disrespectful ridiculous pointless dumb nonsense '
               'bullshit crap rotten dissent resentment'.split())
SUPPORT = {'support', 'supporting'}
DISTRESS = set('grief grieving mourning painful painfully uncomfortable ashamed '
              'shame embarrassing embarrassed embarrassment awkward timid trembling '
              'frightened poignant clumsy'.split())
EMOTION = set('compassionate compassion courage courageous rejoice rejoicing '
             'hilarious terrible offended'.split())

CJK_TRUST = set('信任 信赖 信賴 信頼'.split())
CHINESE_JUDGMENT = set('肯定 认可 認可 认同 認同 满意 滿意 满意度 滿意度 '
                       '拥护 擁護 颂 頌 批评 批評 骂 罵 恨 不满 不滿 放心'.split())
CHINESE_FEELINGS = set('思念 人心 怨 抱怨 依赖 依賴 感激 感动 感動 欣赏 欣賞 '
                       '谅解 諒解 分歧 崇拜 惦 惦记 惦記 赞誉 讚譽 赞赏 讚賞 '
                       '耐心 烦 煩 恋人 戀人 失落 信心'.split())
CHINESE_SUPPORT = set('支持 的支持 扶持 配套'.split())

# Fitted class averages; not arbitrary vocabulary entries.
WORD_CLASSES = (
    (TRUST, -0.42), (TRUST_FORMS, -0.28),
    (RELIANCE, -0.18), (PRAISE, -0.46),
    (APPROVAL, -0.18), (CRITICISM, -0.21), (SUPPORT, -0.11),
    (DISTRESS, 0.26), (EMOTION, 0.18),
    (CJK_TRUST, -0.80), (CHINESE_JUDGMENT, -0.51),
    (CHINESE_FEELINGS, -0.30), (CHINESE_SUPPORT, -0.235),
)

# E9 A0 is the two-byte UTF-8 prefix of U+9800..U+983F:
# head/page-radical characters including 頁, 頃, 須 and 頑.
HEAD_RADICAL_UTF8_PREFIX = 79888
SOCIAL_EVALUATION = APPROVAL | CRITICISM | SUPPORT
RELIANCE_FORMS = RELIANCE | TRUST_FORMS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        position, previous = carry[1] + 1, carry[2]
    text = prefix.token_strings[-1]
    word = text.strip()
    lower = word.lower()
    value = 0.0
    for words, average in WORD_CLASSES:
        if lower in words:
            value = average
            break

    # Particularly strong forms within the broader classes.
    if lower == "painfully":
        value = 0.63
    elif lower == "clumsy":
        value = 0.53
    elif lower == "contempt":
        value = -0.51
    elif lower == "subcommittee":
        value = 0.62
    elif word == "onBindViewHolder":
        value = 0.64
    elif prefix.token_ids[-1] == HEAD_RADICAL_UTF8_PREFIX:
        value = -0.38
    elif (word == "�" and previous == "�"
          and prefix.token_ids[-2] == HEAD_RADICAL_UTF8_PREFIX):
        value = -0.095
    elif word in {"骂", "罵"}:
        value = -0.72
    elif word == "的信任":
        value = -0.80
    elif word in {"ダメ", "ですね"}:
        value = -0.33

    # Secondary formatting and programming-language responses.
    if text == "\r":
        value = -0.11
    elif text == "\\t":
        value = -0.044
    elif len(text) > 1 and all(c == "\xa0" for c in text):
        value = -0.125 * min(len(text), 8) / 8
    elif text == "··":
        value = -0.055
    elif text == "<|im_start|>":
        value = -0.018
    elif text in {"</tool_call>", "</think>"}:
        value = 0.081
    elif lower == "/workspace":
        value = 0.134
    elif lower == "/tests":
        value = -0.15
    elif lower == "/test":
        value = -0.055
    elif word == "@":
        value = 0.062
    elif word in {".Printf", ".printf"}:
        value = 0.145
    elif word in {".xlabel", ".ylabel", ".zlabel"}:
        value = -0.27

    # Grammatical attachments to a preceding social-evaluation word.
    if previous in TRUST:
        if text == "s":
            value -= 0.22
        elif lower in {"in", "of", "for"}:
            value -= 0.31
        elif lower == "that":
            value -= 0.19
        elif lower in {"me", "us", "them", "you", "the"}:
            value -= 0.08
    elif previous in RELIANCE_FORMS and lower in {"in", "of", "on"}:
        value -= 0.11
    elif previous in PRAISE and lower == "of":
        value -= 0.30
    elif previous in SOCIAL_EVALUATION:
        if lower in {"of", "for", "with", "from"}:
            value -= 0.10

    # The onset offset is larger for a document-initial chat boundary.
    if position == 0:
        value -= 0.04
        if text == "<|im_start|>":
            value = -0.14
    elif position == 1:
        value -= 0.012

    return (doc, position, lower), float(value)

