    'according': 5.4, 'accordance': 3.07, 'pursuant': 0.98,
    'selon': 3.75, 'según': 4.05, 'acordo': 3.7, 'acuerdo': 2.95,
    'secondo': 2.22, 'segundo': 1.62, 'согласно': 5.1,
    'соответствии': 2.1, 'соглас': 1.8, 'gemäß': 1.5, 'ตาม': 2.24,
    'によ': 1.93, 'という': 0.68, 'ので': 0.58,
    'apparently': 1.55, 'reportedly': 1.76, 'allegedly': 1.1,
    'supposedly': 1.22, 'accordingly': 1.3, 'depending': 1.0,
