    (2.3, {'described', 'cited', 'evidenced', 'guided', 'governed'}),
    (1.65, {'defined', 'recognized', 'explained', 'required', 'established', 'owned'}),
    (1.25, {'determined', 'shown', 'supported', 'given', 'reported'}),
    (-0.5, {'followed', 'divided', 'separated', 'joined', 'multiply', 'multiplied'}),
    (-0.06, {'caused', 'obtained', 'affected', 'achieved', 'replaced'}),
)
