            value = 2.7 + (0.4 if previous.strip()[:1].isupper() else 0.0)
        elif prev in {'depending', 'depends', 'depend', 'rely', 'relying'}:
            value = 1.5 if prev == 'depending' else 0.75
    elif word == 'in' and prev in REFERENCES:
        value = 0.85 if prev in EVIDENCE else 0.5
    elif word in REFERENCES and prev == 'as':
        value = 0.9
    elif word == 'with' and prev == 'accordance':
        value = 1.91
    elif word in {'basis', 'based', 'due'}:
        value = 0.4
    elif word == 'по':
        value = 2.58 if raw.strip()[:1].isupper() else 1.75
    elif word in {'por', 'nach'}:
        value = 0.55
    elif word in {'据', '據'}:
