                return None, 7.5
            if word == "on" and previous in {"based", "depends"}:
                return None, 1.8
            if word == "in" and previous == "described":
                return None, 0.7

    return None, 0.0

programs.sol:
"""Approximate an orthographic syllable detector, not a semantic classifier.

Short Latin syllables ending in i/u dominate, especially bi/pi/mi/fi, as does
'so'. Word boundaries and capitals strengthen most responses; word interiors
and backslash-prefixed Greek names weaken them. Longer i-endings are weaker.
It also handles Greek names/symbols, Cyrillic pi/ni, technical forms (CI,
pH, fn, sin), and negative located/working responses. The rules miss many token-specific details of the real component.
"""
READS = ()
VOWELS = 'aeiou'
I_ONSETS = (
    ('bpmf', 2.30), ('shknqwx', 1.85), ('cgvyt', 1.45),
    ('alrj', 1.10), ('dz', 0.50), ('u', 0.55),
)
U_ONSETS = (
    ('m', 1.85), ('hntp', 1.10), ('cgjlrsfvkwxy', 0.80), ('bdz', 0.30),
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, run = ('', '') if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.lstrip(' \t\n\r_./-\\([{')
    lower = word.lower()
    marked = word != token
    internal = not marked and previous[-1:].isalpha()
    capital = word[:1].isupper()
    macro = not marked and previous.rstrip().endswith('\\')
    value = 0.0

    if lower == 'so':
        value = 0.84 if not internal else 0.34
    elif word in {'pH', 'PH'}:
        value = 0.80 if marked else 0.65
    elif lower == 'fn':
        value = 0.40
    elif len(lower) == 2 and lower.isascii() and lower.isalpha():
        onset, vowel = lower
        groups = I_ONSETS if vowel == 'i' else U_ONSETS if vowel == 'u' else ()
        value = next((v for letters, v in groups if onset in letters), 0.0)
        if value:
            if capital:
                value += 0.35 if vowel == 'i' and onset not in VOWELS else 0.15
                if word.isupper() and marked and onset not in VOWELS:
                    value += 0.30 if vowel == 'i' else 0.0
            if internal and (not capital or word.isupper()):
                factor = 0.50
                if vowel == 'i' and onset in 'alrtu':
                    factor = 0.25
                elif vowel == 'i' and onset in 'ms':
                    factor = 0.60
                if word.isupper() and onset in 'dn':
                    factor = 0.80
                value *= factor
            if lower == 'fi' and token.startswith('-'):
                value = 0.95  # The ending of Wi-Fi/hi-fi.
            if lower == 'ci':
                if run.lower().endswith(('circle', 'golang')):
                    value = 2.10  # Continuous-integration names.
                elif token.startswith('.'):
                    value = 2.50
            if macro:
                value = 0.72
        elif vowel == 'o' and onset in 'mhb':
            value = (0.65 if onset in 'mh' else 0.30) * (0.4 if internal else 1)
        elif vowel == 'a' and onset in 'mhpvwcgfks':
            value = 0.35 if onset in 'mhpw' else 0.20
            value = (value + 0.10 * capital) * (0.15 if internal else 1)
    elif lower in {'chi', 'phi', 'psi'}:
        value = 1.15 if not internal else 0.55
        value += 0.30 * capital
        if macro:
            value = 0.25
    elif lower.isascii() and lower.isalpha() and lower.endswith('i'):
        if len(lower) > 2:
            value = 0.10 if len(lower) > 6 else 0.25
            if len(lower) == 3 and all(c not in VOWELS for c in lower[:2]):
                value = (0.35 if internal else 0.55) + 0.15 * word.isupper()
            if token.startswith('-'):
                value *= 0.25
        elif lower == 'i' and not marked:
            value = 0.10 if capital else 0.15
    elif lower == 'u' and not marked:
        value = 0.15
    elif lower == 'sin':
        value = 0.32 + 0.30 * capital
    elif word in {'π', 'μ'}:
        value = 0.30 if marked else 0.07
    elif lower in {'пи', 'ни'} and marked:
        value = 0.85 if lower == 'пи' else 1.05
    elif lower == 'located':
        value = (-0.98 if not internal else -0.13) * (0.6 if capital else 1)
    elif lower == 'working':
        value = -0.85 if previous.strip().lower() == 'current' else -0.24

    if any(ch.isspace() for ch in token):
        pieces = token.split()
        run = pieces[-1] if pieces else ''
    else:
        run += token
    return (doc, token, run[-32:]), float(value)

"""A negative detector for repeated-letter tokens, strongest on ii, II, and III.

Strip surrounding whitespace and a few delimiters, then recognize repeated
Latin letters, Roman numerals, short i/j combinations, selected doubled signs,
and Cyrillic repeats. Case, run length, and leading spaces set pulse strength.
A previous vowel or non-ASCII token attenuates some joined lowercase repeats;
that context never crosses documents. Space-prefixed || is weakly positive.
Unrecognized tokens return zero; their small lexical variations are omitted.
"""
READS = ()

# Letter groups distinguish especially strong, moderate, and weak repeats.
def double_strength(ch):
    for letters, strength in (
        ('juy', 2.2), ('aqv', 1.5), ('hnwz', 1.0),
        ('klmort', 0.75), ('efgps', 0.5), ('bcd', 0.25),
    ):
        if ch in letters:
            return strength
    return 0.0

ROMAN = {
    'IV': 0.45, 'VI': 0.35, 'VII': 1.5, 'VIII': 1.55,
    'IX': 0.08, 'XI': 0.3, 'XII': 1.7, 'XIII': 1.35,
    'XIV': 1.0, 'XVI': 0.9,
}
PUNCTUATION = {
    '++': 0.82, "''": 0.88, '""': 0.5, ';;': 0.74,
    '||': 0.2, '!!': 0.22, '??': 0.26, '~~': 0.28, ',,': 0.45,
}


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    t = s.strip().strip('()[]_-.')
    low = t.lower()
    space = s.startswith(' ')
    strength = 0.0
    if len(t) >= 2 and len(set(t)) == 1 and low[0] in 'abcdefghijklmnopqrstuvwxyz':
        ch = low[0]
        strength = double_strength(ch)
        if ch == 'i':
            pair = len(t) == 2
            if pair:
                strength = 3.65 if t.isupper() else 4.45
                if space:
                    strength -= 0.8 if t.isupper() else 0.74
            else:
                strength = 2.63 if t.isupper() else 3.48
                if space:
                    strength -= 0.2 if t.isupper() else 0.55
            if not space and s != t:
                strength *= 0.83
        elif ch == 'x':
            if t.isupper():
                strength = 1.9 if len(t) == 2 else 1.1
            else:
                strength = 2.75 if len(t) == 2 else 1.5
            if space:
                strength *= 0.53 if t.isupper() else 0.67
        else:
            if len(t) > 2:
                strength = 1.5 if ch == 'a' else 0.8
                if low == 'www':
                    strength = 0.55 if t.isupper() else 0.04
            if space:
                strength *= 0.9
        if len(t) > 4:
            strength *= 0.2
        # Only the adjacent token in the same document supplies context.
        same_document = (len(prefix.token_strings) > 1 and
                         prefix.document_ids[-2] == prefix.document_ids[-1])
        if t.islower() and not space and same_document and ch != 'x':
            previous = prefix.token_strings[-2]
            if not previous.isascii():
                strength *= 0.8
            elif previous and previous[-1].lower() in 'aeiouy':
                strength *= 0.85
    elif t.upper() in ROMAN:
        strength = ROMAN[t.upper()]
        if t.islower():
            strength = 0.44 if space and t == 'iv' else strength * 0.2
        elif space and t == 'IV':
            strength = 0.75
        elif space and t == 'VI':
            strength = 0.44
        elif space and t == 'IX':
            strength = 0.45
    elif low in ('ij', 'ji', 'iji'):
        strength = 0.95 if low == 'ji' else 0.65
        if t.istitle() and space:
            strength *= 0.5
    elif t in PUNCTUATION:
        strength = PUNCTUATION[t] * (1.0 if s == t else 0.5)
        if space and t == '||':
            strength = -0.07
    elif t in ('ии', 'ий', 'ее', 'сс', 'мм'):
        strength = {'ии': 0.72, 'ий': 0.42, 'ее': 0.52,
                    'сс': 0.26, 'мм': 0.5}[t]
        if space and t == 'ее':
            strength = 0.16
    return None, float(-strength)

programs.haiku:
"""Roman-numeral and repeated-letter detector (layers.0.mlp.down_proj, component 1338).

The component is silent on nearly every token. It goes negative on short tokens that look
like Roman numerals or a single letter stuttered, and the more "i-like" the token, the
stronger the response:

- runs of the letter i, as in "ii", "iii", "(ii)": strongly negative, about -4;
- upper-case runs of I, as in "II", "III", "-II": about -3;
- other upper-case Roman numerals, as in "IV", "VIII", "XX": mildly negative, about -0.7;
- one letter repeated, as in "mm", "ss", "aa", "xx": mildly negative, about -0.6.

Brackets, hyphens and spaces are ignored first, so "(ii" counts as "ii". Contractions such
as "'ll" are not stutters and stay at 0. Everything else predicts 0.

The program reads only the newest token, so it has no state and needs no document handling.
"""

import re

READS = ()

IGNORED = re.compile(r"[\s()\[\]\-]")


def step(carry, prefix, upstream):
    token = IGNORED.sub("", prefix.token_strings[-1])
    if re.fullmatch(r"i{2,}", token):
        value = -4.0
    elif re.fullmatch(r"I{2,}", token):
        value = -2.9
    elif re.fullmatch(r"[IVX]{2,}", token):
        value = -0.7
    elif re.fullmatch(r"([A-Za-z])\1+", token):
        value = -0.6
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Flag adjacent repeated characters, especially Roman-numeral I and X.

Repeated letters and punctuation are associated with this component's larger
negative responses.  The stronger value for repeated I/X reflects the
especially strong Roman-numeral examples; this remains a text-only heuristic.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    repeated = [
        left.casefold()
        for left, right in zip(token, token[1:])
        if left == right and (left.isalpha() or left.isdigit() or left in "+-'\"")
    ]
    if not repeated:
        return None, 0.0
    if any(char in ("i", "x") for char in repeated):
        return None, -0.24
    if any(char in ("a", "l", "t", "w") for char in repeated):
        return None, -0.12
    if "+" in repeated:
        return None, -0.095
    return None, -0.062

programs.sol:
"""A local speaker/addressee contrast, strongest on 'you', 'your', and 'our'.

Count recent first- and second-person pronouns with 16- and 64-token fading
memories. Repeated address strengthens negative 'you/your' and positive 'our';
speaker mentions weaken them. Logarithms make repetition saturate. Case,
leading whitespace, a few grammatical phrases, and contractions adjust the result.
A small set of translated pronouns receives fixed responses.
All memories restart at document boundaries. Other words normally return zero.
"""
import math

READS = ()
ADDRESSEE = {'you', 'your', 'yours', 'yourself', 'yourselves'}
SPEAKER = {'i', 'me', 'my', 'mine', 'we', 'us', 'our', 'ours', 'ourselves'}
CONDITIONAL = {'if', 'when', 'where', 'how', 'what', 'whether', 'once', 'unless'}
QUESTION = {'do', 'does', 'did', 'are', 'were', 'can', 'could', 'would',
            'will', 'should', 'have', 'had'}
HELP = {'help', 'helps', 'helping', 'assist', 'guide', 'enable', 'allow', 'support'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', False, (0., 0., 0., 0.), 0.)
    _, age, prev, prev_cap, counts, last = carry
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    capital = token.strip()[:1].isupper()
    spaced = token[:1].isspace()
    you16, we16, you64, we64 = map(math.log1p, counts)
    speaker = 0.28*we16 + 0.17*we64
    address = 0.10*you16 + 0.28*you64
    value = 0.0

    if word in {'you', 'your'}:
        value = (-0.61 if word == 'you' else -0.85) + speaker - address
        value += 0.035*math.log1p(age)
        if capital:
            value += 0.35 if word == 'you' else 0.16
        elif prev in CONDITIONAL:
            value -= 0.27 if word == 'you' else 0.15
        elif prev in QUESTION:
            value += 0.20 + 0.18*prev_cap
        elif prev in HELP:
            value -= 0.33 if word == 'you' else 0.18
        elif word == 'you' and prev in {'thank', 'thanks'}:
            value += 0.22
        if age and not any(c.isalpha() for c in prev):
            value += 0.20 if word == 'you' else 0.29
        if age == 0:
            value -= 0.49 if word == 'you' else 0.79
        elif age < 3:
            value -= 0.12
        if not spaced:
            value = 0.55*value + (0.18 if capital else 0.0)
    elif word == 'yourself':
        value = -0.48 - 0.09*you16 - 0.12*you64 + 0.10*we64
    elif word == 'our':
        value = 0.56 + 0.33*you16 + 0.19*you64 - 0.27*we16 - 0.07*we64
        value -= 0.01*math.log1p(age)
        if capital:
            value = 0.50 + 0.20*you16 + 0.30*you64 - 0.05*we16 - 0.16*we64
        elif not spaced:
            value *= 0.25
        if age == 0:
            value -= 0.24
    elif prev == 'you' and word in {"'re", '’re', 'are'}:
        value = 0.40*last + (0.07 if word == 'are' else -0.08)
    elif prev == 'we' and word in {"'re", '’re'}:
        value = 0.13
    elif word in {'你', '您'}:
        value = -0.16 if word == '你' else -0.28
    elif word in {'你的', '您的', 'ваш', 'вам', 'вас', 'votre', 'você', 'bạn'}:
        value = -0.43
    elif word in {'наш', 'наша', 'наше', 'наши', 'нашем', 'наших', 'notre'}:
        value = 0.50

    mentions = (word in ADDRESSEE, word in SPEAKER)*2
    rates = (0.939413, 0.939413, 0.984496, 0.984496)
    counts = tuple(rate*count + hit
                   for count, rate, hit in zip(counts, rates, mentions))
    return (doc, age + 1, word, capital, counts, value), float(value)

programs.haiku:
"""Second-person 'you' words push the activation negative: strongly when 'you' is the reader
being addressed in an if/when/once clause or a how-to sentence, weakly after a question
auxiliary ('Do you', 'Can you'), and more so the more the document has already said
'you'/'your'. 'our' pushes the activation positive."""

READS = ()

# "you" right after a question auxiliary ("Do you", "Can you") is a question, not advice.
QUESTION_AUX = {"do", "did", "does", "can", "could", "are", "would", "will", "should", "were", "is", "have", "had", "may", "might"}
# "you" right after a conjunction or verb of help: a clause addressing the reader.
CLAUSE_START = {"if", "unless", "when", "once", "before", "after", "because", "while", "until", "help", "helps", "ensure", "guide", "support", "allows", "allow"}

YOUR = {" your": -0.8, " Your": -0.55, "your": -0.3, "Your": -0.4, " yourself": -0.7, " yours": -0.2, "YOUR": -0.25}
YOU = {" you", "you"}
OUR = {" our": 0.45, " Our": 0.6, "Our": 0.45, "our": 0.4}
OTHER_LANG = {" bạn": -0.5, " вас": -0.5, " вам": -0.5, " ваш": -0.4, "您": -0.2, "您的": -0.4, "你的": -0.25, " votre": -0.3, " você": -0.35, "あなた": -0.2, " наш": 0.4, "我们的": 0.3}


def step(carry, prefix, upstream):
    # carry: (document id, how many 'you'/'your' the document has used so far)
    doc = prefix.document_ids[-1]
    seen = carry[1] if carry is not None and carry[0] == doc else 0
    word = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word in OUR:
        return (doc, seen), float(OUR[word])
    if word in YOUR:
        return (doc, seen + 1), float(YOUR[word])
    if word in YOU:
        value = -0.3 - 0.07 * min(seen, 5)
        if prev in QUESTION_AUX:
            value += 0.27
        elif prev in CLAUSE_START:
            value -= 0.4
        return (doc, seen + 1), float(value)
    if word == " You" or word == "You":
        return (doc, seen), -0.2
    return (doc, seen), float(OTHER_LANG.get(word, 0.0))

programs.sol:
"""Approximate the largest observed responses with spelling and chat structure.

Training examples are dominated by negative responses to user-role headers
and short Arabic-script heh fragments, not a single semantic topic.
Unspaced standalone heh is strongest; attached letters usually weaken it.
Document-local Persian/Arabic letter evidence adjusts its strength.
Smaller rules cover ta-marbuta, isolated H-like letters in other scripts,
ASCII nh endings, legal deictic compounds, and chat delimiters.
Other text is neutral. Weak lexical and partial-byte effects are omitted.
"""
READS = ()
PERSIAN_LETTERS = frozenset('پچژگکی')
ARABIC_LETTERS = frozenset('ةيىأإؤ')


def lexical_response(token, language):
    word = token.strip()
    n = len(word)
    spaced = token.startswith(' ')
    if word.endswith('هذه'):
        return -0.4
    if word == 'ھ':
        return -1.3
    if word == 'ہ':
        return -4.1
    if word.endswith('ه'):
        if n == 1:
            return -2.05 + 0.2*language if spaced else -4.7 + 0.65*language
        if n == 2:
            if spaced:
                return -3.55
            value = -3.95 + 0.3*language
            if word[0] in 'اش':
                value += 0.65
            elif word[0] == 'د':
                value -= 0.45
            return value
        if n <= 4:
            return -2.4 if n == 3 or spaced else -0.6
        return -0.3
    if word.endswith('ها'):
        return -max(0.3, 3.5 - 0.4*n - 0.7*spaced) + 0.25*language
    if word in ('هم', 'هما'):
        return -1.8
    if word.endswith('ة'):
        return -1.0 / n
    if word == 'ह':  # Devanagari ha
        return -2.8 if spaced else -3.7
    if word in ('ה', 'ห', 'へ'):  # Hebrew he, Thai ho, Japanese he
        return -1.1 if word == 'ה' else -0.54
    if word == 'thereof':
        return -1.7
    if word == 'therein':
        return -0.68
    if word.isascii() and len(word) > 2 and word.endswith('nh'):
        return -1.3 if word == 'enh' and not spaced else -0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        carry = (doc, '', 0)
    _, previous, spelling = carry
    token = prefix.token_strings[-1]
    spelling += sum(c in PERSIAN_LETTERS for c in token)
    spelling -= sum(c in ARABIC_LETTERS for c in token)
    language = (spelling > 0) - (spelling < 0)
    value = lexical_response(token, language)
    if token == 'user' and previous == '<|im_start|>':
        value = -1.43
    elif token == '<|im_start|>' and first:
        value = -0.42
    elif token == '<tool_response>':
        value = 0.2
    return (doc, token, spelling), float(value)

programs.haiku:
"""Persian heh-suffix detector v4.

Fires negatively on the Persian/Arabic letter heh (ه, and its look-alikes) when it ends a
word or sits as a suffix, and on the role word "user" right after "<|im_start|>".
"""

READS: tuple[str, ...] = ()

HEH_LETTERS = "هہھۀ"  # heh and its Urdu/Persian variants
HEH_ALEF = "ها"  # the plural/pronoun suffix written heh + alef
TEH_MARBUTA = "ة"  # feminine ending
LEGAL_ADVERBS = ("thereof", "therein")


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if s == "user" and before == "<|im_start|>":
        return None, -1.4
    if any(c in s for c in HEH_LETTERS):
        if s in tuple(HEH_LETTERS):
            return None, -4.0  # a lone heh token
        if s[-1] in HEH_LETTERS:
            return None, -3.0  # word ends in heh
        if s.endswith(HEH_ALEF):
            return None, -2.5  # ends in heh-alef suffix
        if s[0] in HEH_LETTERS:
            return None, -1.5  # starts with heh (هم, هر)
        return None, -0.5  # heh inside the token
    if s.endswith(HEH_ALEF):
        return None, -2.5
    if s.endswith(TEH_MARBUTA):
        return None, -0.5
    if s in LEGAL_ADVERBS:
        return None, -1.4
    return None, 0.0

"""layers.0.mlp.down_proj:1343 as a "numbered label" detector.

The component is mostly a token-identity feature, and it is negative. Its strongest
responses come on the words that open an ordinal or numbered label, after which a number
or ordinal is expected:

- the Chinese ordinal marker 第 (第一, 第二, 第三 ...; the bare 第 is strongest),
- the Korean ordinal prefixes 제 and 최,
- the symbols § and № (section, number),
- a few Chinese quantifiers: 每 (every), 最 (most), 前 (before), 共 (together).

Weaker negatives come on English section and unit nouns (Step, Part, Page, Chapter,
Article, Section, Lesson, Question, Vol, Case, ...) and on month and weekday names.
Every other token predicts 0. The program is stateless: it reads only the newest token.
"""

MONTHS_WEEKDAYS = {
    "january", "february", "march", "april", "june", "july", "august", "september",
    "october", "november", "december", "monday", "tuesday", "wednesday", "thursday",
    "friday", "saturday", "sunday",
}
SECTION_NOUNS = {
    "step", "part", "page", "chapter", "article", "section", "lesson", "question", "vol",
    "stage", "episode", "grade", "rule", "unit", "problem", "issue", "volume", "figure",
    "item", "version", "act",
}
QUANTIFIERS = {"最", "每", "前", "共"}


def value(token: str) -> float:
    """Predicted activation for one token, decoded alone."""
    word = token.strip()
    if token == "第":
        return -9.0          # bare ordinal marker: strongest
    if token == " 第":
        return -7.0
    if token == " 제":
        return -6.0
    if "第" in token:
        return -3.5          # 第一, 第二, 第三 ... (ordinal words)
    if word in ("제", "최"):
        return -2.0
    if word in ("§", "№", "§§"):
        return -1.2
    if word in QUANTIFIERS:
        return -1.0
    lower = word.lower().strip(".")
    if lower in SECTION_NOUNS:
        return -0.2
    if lower in MONTHS_WEEKDAYS:
        return -0.5
    return 0.0


READS = ()


def step(carry, prefix, upstream):
    """Activation at the newest token, from its own text alone (no carried state)."""
    return carry, float(value(prefix.token_strings[-1]))

programs.luna:
"""Recognize named dates and capitalized labels for numbered divisions.

The strongest sampled responses are on dates, section/page/part labels, and
Chinese ordinal markers.  Capitalization keeps ordinary words such as “may”
separate from month names.
"""
READS = ()

MONTHS = frozenset(("January February March April May June July August "
                    "September October November December").split())
WEEKDAYS = frozenset(("Monday Tuesday Wednesday Thursday Friday Saturday "
                      "Sunday").split())


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in MONTHS:
        value = -0.52
    elif word in WEEKDAYS:
        value = -0.65
    elif word == "№":
        value = -1.8
    elif word in ("Section", "section"):
        value = -0.4
    elif word == "Vol":
