        value = -0.8
    elif word == "Part":
        value = -0.9
    elif word == "step":
        value = -0.6
    elif word == "第二" or "第" in word:
        value = -3.5
    elif word == "前":
        value = -0.8
    elif word == "每":
        value = -1.1
    elif word == "篇":
        value = -0.4
    elif word == "제":
        value = -2.0
    else:
        value = 0.0
    return None, float(value)
